{
  "name": "AI Project Auditor",
  "description": "An automated auditing tool for analyzing social investment project proposals from PDF files using Gemini AI."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface AnalysisStep {
  id: string;
  label: string;
  status: 'pending' | 'loading' | 'completed' | 'error';
  response?: string;
}

export interface ProjectAnalysis {
  pageNumber: number;
  rawText: string;
  status: 'pending' | 'analyzing' | 'completed' | 'error';
  currentStepIndex: number;
  finalReport?: string;
  error?: string;
  steps: AnalysisStep[];
}

export enum AnalysisStage {
  IDLE = 'IDLE',
  PROCESSING = 'PROCESSING',
  COMPLETED = 'COMPLETED',
}

export interface PdfPage {
  pageNumber: number;
  text: string;
}

import * as pdfjsLib from 'pdfjs-dist';
import { PdfPage } from '../types';
import { IGNORED_PAGES } from '../constants';

// Set the worker source for pdfjs-dist
// Using a specific version matching common usage to avoid version mismatch errors
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

export const extractTextFromPdf = async (file: File): Promise<PdfPage[]> => {
  const arrayBuffer = await file.arrayBuffer();
  const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
  const pdf = await loadingTask.promise;

  const pages: PdfPage[] = [];

  for (let i = 1; i <= pdf.numPages; i++) {
    // Check if page should be ignored (1-based index)
    if (IGNORED_PAGES.includes(i)) {
      continue;
    }

    try {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const text = textContent.items
        .map((item: any) => item.str)
        .join(' ')
        .replace(/\s+/g, ' ') // normalize whitespace
        .trim();

      // Only add pages that have some content
      if (text.length > 50) { 
        pages.push({
          pageNumber: i,
          text: text
        });
      }
    } catch (error) {
      console.error(`Error processing page ${i}:`, error);
    }
  }

  return pages;
};

import { GoogleGenAI, Chat } from "@google/genai";
import { 
  INITIAL_CONTEXT_PROMPT, 
  PROMPT_CRITERIA_1, 
  PROMPT_CRITERIA_2, 
  PROMPT_CRITERIA_3, 
  PROMPT_FINAL_REPORT 
} from "../constants";

const getClient = () => {
    // API Key must be obtained exclusively from the environment variable
    if (!process.env.API_KEY) {
        throw new Error("API Key is missing. Please set process.env.API_KEY.");
    }
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const createAuditSession = () => {
  const ai = getClient();
  // Using gemini-2.5-flash as it is efficient for text analysis tasks
  return ai.chats.create({
    model: 'gemini-2.5-flash',
    config: {
      temperature: 0.2, // Low temperature for rigorous, factual output
      candidateCount: 1,
    }
  });
};

export const runAuditSequence = async (
  session: Chat, 
  projectText: string,
  onStepComplete: (stepId: string, response: string) => void
): Promise<string> => {

  // 1. Initial Setup & Context
  const initPrompt = INITIAL_CONTEXT_PROMPT(projectText);
  const initResponse = await session.sendMessage({ message: initPrompt });
  onStepComplete('init', initResponse.text || "Auditor Mode Activated");

  // 2. Criteria 1
  const c1Response = await session.sendMessage({ message: PROMPT_CRITERIA_1 });
  onStepComplete('criteria1', c1Response.text || "Criteria 1 Analyzed");

  // 3. Criteria 2
  const c2Response = await session.sendMessage({ message: PROMPT_CRITERIA_2 });
  onStepComplete('criteria2', c2Response.text || "Criteria 2 Analyzed");

  // 4. Criteria 3
  const c3Response = await session.sendMessage({ message: PROMPT_CRITERIA_3 });
  onStepComplete('criteria3', c3Response.text || "Criteria 3 Analyzed");

  // 5. Final Report
  const finalResponse = await session.sendMessage({ message: PROMPT_FINAL_REPORT });
  const finalText = finalResponse.text || "Report Generated";
  onStepComplete('final', finalText);

  return finalText;
};

import React, { useState } from 'react';
import { ProjectAnalysis } from '../types';

interface Props {
  project: ProjectAnalysis;
}

const ProjectCard: React.FC<Props> = ({ project }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  // Extract score if possible from final report (simple regex for display)
  const extractScore = (text?: string) => {
    if (!text) return null;
    const match = text.match(/ÍNDICE DE PRIORIDADE BV:\*\*.*?(\d+)/);
    return match ? parseInt(match[1]) : null;
  };

  const score = extractScore(project.finalReport);
  const isFinished = project.status === 'completed';
  const isAnalyzing = project.status === 'analyzing';

  const getStatusColor = () => {
    if (project.status === 'error') return 'border-red-500 bg-red-50';
    if (isAnalyzing) return 'border-blue-500 bg-blue-50';
    if (!isFinished) return 'border-gray-200 bg-white';

    // Score based coloring
    if (score !== null) {
      if (score >= 70) return 'border-green-500 bg-white';
      if (score >= 40) return 'border-yellow-500 bg-white';
      return 'border-red-400 bg-white';
    }
    return 'border-gray-200 bg-white';
  };

  return (
    <div className={`border-l-4 rounded-lg shadow-sm mb-4 transition-all duration-300 ${getStatusColor()}`}>
      <div 
        className="p-4 cursor-pointer flex justify-between items-center"
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="flex items-center gap-4">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white ${
                project.status === 'completed' ? (score && score > 60 ? 'bg-green-600' : 'bg-yellow-600') : 'bg-gray-400'
            }`}>
                {project.pageNumber}
            </div>
            <div>
                <h3 className="font-semibold text-lg text-gray-800">
                    Project (Page {project.pageNumber})
                </h3>
                <p className="text-xs text-gray-500 truncate max-w-md">
                   {project.rawText.substring(0, 80)}...
                </p>
            </div>
        </div>

        <div className="flex items-center gap-4">
            {isAnalyzing && (
                <div className="flex flex-col items-end">
                     <span className="text-xs font-semibold text-blue-600 animate-pulse">Analyzing Step {project.currentStepIndex + 1}/5</span>
                     <div className="w-24 h-1 bg-gray-200 rounded-full mt-1">
                        <div 
                            className="h-full bg-blue-600 rounded-full transition-all duration-500"
                            style={{ width: `${((project.currentStepIndex + 1) / 5) * 100}%` }}
                        ></div>
                     </div>
                </div>
            )}
            {isFinished && score !== null && (
                 <div className="text-right">
                    <span className="block text-sm text-gray-500 uppercase font-bold tracking-wider">Priority Index</span>
                    <span className="text-2xl font-bold text-gray-800">{score}/100</span>
                 </div>
            )}
             <i className={`fas fa-chevron-down text-gray-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`}></i>
        </div>
      </div>

      {isExpanded && (
        <div className="p-4 border-t border-gray-100 bg-white rounded-b-lg">
            {project.error && (
                <div className="p-3 bg-red-100 text-red-700 rounded mb-4">
                    Error: {project.error}
                </div>
            )}

            {project.finalReport ? (
                <div className="prose prose-sm max-w-none prose-headings:text-bv-blue">
                    <pre className="whitespace-pre-wrap font-sans text-sm text-gray-700 leading-relaxed">
                        {project.finalReport}
                    </pre>
                </div>
            ) : (
                <div className="space-y-2">
                    <p className="text-sm font-semibold text-gray-500 mb-2">Analysis Steps Log:</p>
                    {project.steps.map((step) => (
                        <div key={step.id} className="flex items-start gap-2 text-sm">
                            <span className={`w-2 h-2 rounded-full mt-1.5 flex-shrink-0 ${
                                step.status === 'completed' ? 'bg-green-500' : 
                                step.status === 'loading' ? 'bg-blue-500 animate-ping' : 'bg-gray-300'
                            }`}></span>
                            <div className="flex-1">
                                <span className="font-medium text-gray-700">{step.label}</span>
                                {step.response && step.status === 'completed' && step.id !== 'final' && (
                                    <div className="text-xs text-gray-500 mt-1 pl-2 border-l-2 border-gray-200">
                                        {step.response.substring(0, 150)}...
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
      )}
    </div>
  );
};

export default ProjectCard;

import React, { useState } from 'react';
import { ProjectAnalysis, AnalysisStage, AnalysisStep } from './types';
import { extractTextFromPdf } from './services/pdfService';
import { createAuditSession, runAuditSequence } from './services/geminiService';
import ProjectCard from './components/ProjectCard';

const App: React.FC = () => {
  const [stage, setStage] = useState<AnalysisStage>(AnalysisStage.IDLE);
  const [projects, setProjects] = useState<ProjectAnalysis[]>([]);
  const [progress, setProgress] = useState({ current: 0, total: 0 });

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      alert('Please upload a valid PDF file.');
      return;
    }

    setStage(AnalysisStage.PROCESSING);
    setProjects([]);

    try {
      // 1. Extract Pages
      const pages = await extractTextFromPdf(file);

      const initialProjects: ProjectAnalysis[] = pages.map(p => ({
        pageNumber: p.pageNumber,
        rawText: p.text,
        status: 'pending',
        currentStepIndex: 0,
        steps: [
            { id: 'init', label: 'Auditor Mindset Initialization', status: 'pending' },
            { id: 'criteria1', label: 'Criteria 1: Social Impact', status: 'pending' },
            { id: 'criteria2', label: 'Criteria 2: Feasibility', status: 'pending' },
            { id: 'criteria3', label: 'Criteria 3: Proponent Capacity', status: 'pending' },
            { id: 'final', label: 'Final Score Calculation', status: 'pending' },
        ]
      }));

      setProjects(initialProjects);
      setProgress({ current: 0, total: initialProjects.length });

      // 2. Process Sequentially
      await processProjects(initialProjects);

    } catch (error) {
      console.error("Critical Error:", error);
      alert("Failed to process the PDF. Please try again.");
      setStage(AnalysisStage.IDLE);
    }
  };

  const processProjects = async (initialProjects: ProjectAnalysis[]) => {
    // We create a local copy to update state accurately
    let currentList = [...initialProjects];

    for (let i = 0; i < currentList.length; i++) {
        const projectIndex = i;
        setProgress({ current: i + 1, total: currentList.length });

        // Update status to analyzing
        currentList = updateProjectState(currentList, projectIndex, { status: 'analyzing' });
        setProjects([...currentList]);

        try {
            const session = createAuditSession();

            // Define callback to update UI during the 5 steps
            const onStepComplete = (stepId: string, response: string) => {
                setProjects(prevProjects => {
                    const newProjects = [...prevProjects];
                    const p = newProjects[projectIndex];

                    // Mark step as complete
                    const stepIdx = p.steps.findIndex(s => s.id === stepId);
                    if (stepIdx !== -1) {
                        p.steps[stepIdx].status = 'completed';
                        p.steps[stepIdx].response = response;
                        // Start next step loading if exists
                        if (stepIdx + 1 < p.steps.length) {
                             p.steps[stepIdx + 1].status = 'loading';
                             p.currentStepIndex = stepIdx + 1;
                        }
                    }
                    return newProjects;
                });
            };

            // Start first step loading
            setProjects(prev => {
                const copy = [...prev];
                copy[projectIndex].steps[0].status = 'loading';
                return copy;
            });

            // Run the prompt chain
            const finalReport = await runAuditSequence(
                session, 
                currentList[projectIndex].rawText,
                onStepComplete
            );

            // Mark Project Complete
            currentList = updateProjectState(currentList, projectIndex, { 
                status: 'completed',
                finalReport: finalReport
            });
            setProjects([...currentList]);

        } catch (err: any) {
            console.error(`Error analyzing page ${currentList[projectIndex].pageNumber}`, err);
            currentList = updateProjectState(currentList, projectIndex, { 
                status: 'error',
                error: err.message || "AI Analysis Failed"
            });
            setProjects([...currentList]);
        }
    }

    setStage(AnalysisStage.COMPLETED);
  };

  const updateProjectState = (list: ProjectAnalysis[], index: number, updates: Partial<ProjectAnalysis>) => {
      const newList = [...list];
      newList[index] = { ...newList[index], ...updates };
      return newList;
  };

  const downloadAllReports = () => {
      const reportText = projects.map(p => 
          `--- PROJECT PAGE ${p.pageNumber} ---\n\n${p.finalReport || 'Analysis Failed'}\n\n================================\n\n`
      ).join('');

      const blob = new Blob([reportText], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'BV_Project_Audit_Report.txt';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Header */}
      <header className="bg-bv-dark text-white shadow-lg sticky top-0 z-50">
        <div className="container mx-auto px-6 py-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
                <i className="fas fa-robot text-bv-primary text-2xl"></i>
                <div>
                    <h1 className="text-xl font-bold tracking-tight">AI Project Auditor</h1>
                    <p className="text-xs text-gray-400">Automated Social Investment Analysis</p>
                </div>
            </div>
            {stage === AnalysisStage.PROCESSING && (
                <div className="bg-gray-800 px-4 py-2 rounded-lg flex items-center gap-3 border border-gray-700">
                    <div className="w-4 h-4 border-2 border-bv-primary border-t-transparent rounded-full animate-spin"></div>
                    <span className="text-sm font-medium">Processing Project {progress.current} of {progress.total}</span>
                </div>
            )}
            {stage === AnalysisStage.COMPLETED && (
                 <button 
                 onClick={downloadAllReports}
                 className="bg-bv-primary hover:bg-yellow-400 text-bv-dark font-bold py-2 px-4 rounded shadow transition-colors flex items-center gap-2 text-sm"
               >
                 <i className="fas fa-download"></i> Download Full Report
               </button>
            )}
        </div>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-6 py-8 flex-grow">

        {stage === AnalysisStage.IDLE && (
            <div className="max-w-2xl mx-auto mt-20 text-center">
                <div className="bg-white p-10 rounded-2xl shadow-xl border border-gray-100">
                    <div className="w-20 h-20 bg-blue-50 text-bv-blue rounded-full flex items-center justify-center mx-auto mb-6 text-3xl">
                        <i className="fas fa-file-pdf"></i>
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800 mb-2">Upload Project Portfolio</h2>
                    <p className="text-gray-500 mb-8">
                        Upload a PDF file containing project slides. The AI will audit each valid page individually based on the BV Qualitative Criteria Matrix.
                    </p>

                    <label className="relative inline-flex items-center justify-center group cursor-pointer">
                        <div className="absolute transition-all duration-200 rounded-full -inset-px bg-gradient-to-r from-cyan-400 to-blue-600 group-hover:opacity-70 opacity-0 blur-lg"></div>
                        <input 
                            type="file" 
                            accept="application/pdf" 
                            onChange={handleFileUpload}
                            className="hidden" 
                        />
                        <div className="relative bg-bv-blue hover:bg-blue-900 text-white font-semibold py-4 px-8 rounded-full shadow-lg transition-all flex items-center gap-3 text-lg">
                            <i className="fas fa-upload"></i>
                            Select PDF File
                        </div>
                    </label>
                    <p className="mt-4 text-xs text-gray-400">Pages 1, 2, 14, and 24 will be automatically ignored.</p>
                </div>
            </div>
        )}

        {(stage === AnalysisStage.PROCESSING || stage === AnalysisStage.COMPLETED) && (
            <div className="max-w-4xl mx-auto">
                <div className="flex justify-between items-end mb-6">
                    <h2 className="text-xl font-bold text-gray-800 border-l-4 border-bv-primary pl-3">
                        Audit Results
                    </h2>
                    {stage === AnalysisStage.PROCESSING && (
                        <span className="text-sm text-gray-500 animate-pulse">
                            AI is analyzing strictly and skeptically...
                        </span>
                    )}
                </div>

                <div className="space-y-4">
                    {projects.map((project, idx) => (
                        <ProjectCard key={idx} project={project} />
                    ))}
                </div>
            </div>
        )}
      </main>

       {/* Footer */}
       <footer className="bg-white border-t border-gray-200 py-6 mt-8">
            <div className="container mx-auto px-6 text-center text-gray-400 text-sm">
                <p>&copy; {new Date().getFullYear()} AI Auditor System. Internal Use Only.</p>
                <p className="text-xs mt-1">Powered by Gemini 2.5 Flash</p>
            </div>
        </footer>
    </div>
  );
};

export default App;

