import React, { useState } from 'react';
import { ProjectAnalysis } from '../types';

interface Props {
  project: ProjectAnalysis;
}

const ProjectCard: React.FC<Props> = ({ project }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  // Extract data from the final report using Regex
  const extractData = (text?: string) => {
    if (!text) return { score: null, name: null, average: null };

    // Extract Index
    const scoreMatch = text.match(/ÍNDICE DE PRIORIDADE BV:\*\*.*?(\d+)/);
    const score = scoreMatch ? parseInt(scoreMatch[1]) : null;

    // Extract Name
    const nameMatch = text.match(/\*\*NOME DO PROJETO:\*\*\s*(.*)/);
    const name = nameMatch ? nameMatch[1].trim() : "Projeto não identificado";

    // Extract Average
    const avgMatch = text.match(/\*\*MÉDIA TÉCNICA:\*\*\s*([\d,.]+)/);
    const average = avgMatch ? avgMatch[1].trim() : "N/A";

    return { score, name, average };
  };

  const { score, name, average } = extractData(project.finalReport);
  const isFinished = project.status === 'completed';
  const isAnalyzing = project.status === 'analyzing';

  const getStatusColor = () => {
    if (project.status === 'error') return 'border-red-500 bg-red-50';
    if (isAnalyzing) return 'border-blue-500 bg-blue-50';
    if (!isFinished) return 'border-gray-200 bg-white';

    // Score based coloring
    if (score !== null) {
      if (score >= 70) return 'border-green-500 bg-white';
      if (score >= 40) return 'border-yellow-500 bg-white';
      return 'border-red-400 bg-white';
    }
    return 'border-gray-200 bg-white';
