                {!isFinished && (
                  <p className="text-xs text-gray-500 truncate max-w-md">
                    {project.rawText.substring(0, 80)}...
                  </p>
                )}
            </div>
        </div>

        <div className="flex items-center gap-6">
            {isAnalyzing && (
                <div className="flex flex-col items-end">
                     <span className="text-xs font-semibold text-blue-600 animate-pulse">Analisando Etapa {project.currentStepIndex + 1}/5</span>
                     <div className="w-24 h-1 bg-gray-200 rounded-full mt-1">
                        <div 
                            className="h-full bg-blue-600 rounded-full transition-all duration-500"
                            style={{ width: `${((project.currentStepIndex + 1) / 5) * 100}%` }}
                        ></div>
                     </div>
                </div>
            )}
            {isFinished && (
              <>
                 {average && (
                    <div className="text-right hidden sm:block">
                      <span className="block text-xs text-gray-500 uppercase font-bold tracking-wider">Média Téc.</span>
                      <span className="text-xl font-bold text-bv-blue">{average}</span>
                    </div>
                 )}
                 {score !== null && (
                    <div className="text-right">
                        <span className="block text-xs text-gray-500 uppercase font-bold tracking-wider">Índice BV</span>
                        <span className="text-2xl font-bold text-gray-800">{score}/100</span>
                    </div>
                 )}
              </>
            )}
             <i className={`fas fa-chevron-down text-gray-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`}></i>
        </div>
      </div>

      {isExpanded && (
        <div className="p-4 border-t border-gray-100 bg-white rounded-b-lg">
