import React, { useState } from 'react';
import { ProjectAnalysis, AnalysisStage, AnalysisStep } from './types';
import { extractTextFromPdf } from './services/pdfService';
import { createAuditSession, runAuditSequence } from './services/geminiService';
import ProjectCard from './components/ProjectCard';

const App: React.FC = () => {
  const [stage, setStage] = useState<AnalysisStage>(AnalysisStage.IDLE);
  const [projects, setProjects] = useState<ProjectAnalysis[]>([]);
  const [progress, setProgress] = useState({ current: 0, total: 0 });

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      alert('Por favor, envie um arquivo PDF válido.');
      return;
    }

    setStage(AnalysisStage.PROCESSING);
    setProjects([]);

    try {
      // 1. Extract Pages
      const pages = await extractTextFromPdf(file);

      const initialProjects: ProjectAnalysis[] = pages.map(p => ({
        pageNumber: p.pageNumber,
        rawText: p.text,
        status: 'pending',
        currentStepIndex: 0,
        steps: [
            { id: 'init', label: 'Inicializando Auditoria', status: 'pending' },
            { id: 'criteria1', label: 'Critério 1: Impacto Social', status: 'pending' },
            { id: 'criteria2', label: 'Critério 2: Viabilidade', status: 'pending' },
            { id: 'criteria3', label: 'Critério 3: Capacidade', status: 'pending' },
            { id: 'final', label: 'Cálculo de Prioridade e Relatório', status: 'pending' },
        ]
      }));

      setProjects(initialProjects);
      setProgress({ current: 0, total: initialProjects.length });

      // 2. Process Sequentially
      await processProjects(initialProjects);

    } catch (error) {
      console.error("Critical Error:", error);
      alert("Falha ao processar o PDF. Tente novamente.");
      setStage(AnalysisStage.IDLE);
    }
  };

  const processProjects = async (initialProjects: ProjectAnalysis[]) => {
    // We create a local copy to update state accurately
    let currentList = [...initialProjects];

    for (let i = 0; i < currentList.length; i++) {
        const projectIndex = i;
        setProgress({ current: i + 1, total: currentList.length });

        // Update status to analyzing
        currentList = updateProjectState(currentList, projectIndex, { status: 'analyzing' });
        setProjects([...currentList]);

        try {
            const session = createAuditSession();

            // Define callback to update UI during the 5 steps
            const onStepComplete = (stepId: string, response: string) => {
                setProjects(prevProjects => {
                    const newProjects = [...prevProjects];
                    const p = newProjects[projectIndex];

                    // Mark step as complete
                    const stepIdx = p.steps.findIndex(s => s.id === stepId);
                    if (stepIdx !== -1) {
                        p.steps[stepIdx].status = 'completed';
                        p.steps[stepIdx].response = response;
                        // Start next step loading if exists
                        if (stepIdx + 1 < p.steps.length) {
                             p.steps[stepIdx + 1].status = 'loading';
                             p.currentStepIndex = stepIdx + 1;
                        }
                    }
                    return newProjects;
                });
            };

            // Start first step loading
            setProjects(prev => {
                const copy = [...prev];
                copy[projectIndex].steps[0].status = 'loading';
                return copy;
            });

            // Run the prompt chain
            const finalReport = await runAuditSequence(
                session, 
                currentList[projectIndex].rawText,
                onStepComplete
            );

            // Mark Project Complete
            currentList = updateProjectState(currentList, projectIndex, { 
                status: 'completed',
                finalReport: finalReport
            });
            setProjects([...currentList]);

