import { GoogleGenAI, Chat } from "@google/genai";
import { 
  INITIAL_CONTEXT_PROMPT, 
  PROMPT_CRITERIA_1, 
  PROMPT_CRITERIA_2, 
  PROMPT_CRITERIA_3, 
  PROMPT_FINAL_REPORT 
} from "../constants";

const getClient = () => {
    // API Key must be obtained exclusively from the environment variable
    if (!process.env.API_KEY) {
        throw new Error("API Key is missing. Please set process.env.API_KEY.");
    }
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const createAuditSession = () => {
  const ai = getClient();
  // Using gemini-2.5-flash as it is efficient for text analysis tasks
  return ai.chats.create({
    model: 'gemini-2.5-flash',
    config: {
      temperature: 0.2, // Low temperature for rigorous, factual output
      candidateCount: 1,
    }
  });
};

/**
 * Helper function to send messages with retry logic for rate limits (429)
 */
const sendMessageWithRetry = async (session: Chat, message: string, retries = 5, baseDelay = 5000): Promise<string> => {
    for (let i = 0; i < retries; i++) {
        try {
            const result = await session.sendMessage({ message });
            return result.text || "";
        } catch (error: any) {
            // Check for common rate limit or server overload indicators
            // The error object might differ, so we check multiple properties
            const isRateLimit = 
                error.status === 429 || 
                error.code === 429 || 
                (error.message && error.message.includes('429')) ||
                (error.message && error.message.toLowerCase().includes('quota')) ||
                (error.message && error.message.toLowerCase().includes('resource_exhausted'));

            const isServerIssue = error.status === 503 || error.code === 503;

            if ((isRateLimit || isServerIssue) && i < retries - 1) {
                // Exponential backoff: 5s, 10s, 20s, 40s...
                const waitTime = baseDelay * Math.pow(2, i); 
                console.warn(`Limite de taxa atingido (429/503). Tentativa ${i + 1}/${retries}. Aguardando ${waitTime/1000}s...`);
                await new Promise(resolve => setTimeout(resolve, waitTime));
                continue;
            }
            // If it's another error or retries exhausted, throw it
            throw error;
        }
    }
    throw new Error("Número máximo de tentativas excedido devido a limites da API.");
};

export const runAuditSequence = async (
  session: Chat, 
  projectText: string,
  onStepComplete: (stepId: string, response: string) => void
): Promise<string> => {

  // 1. Initial Setup & Context
  const initPrompt = INITIAL_CONTEXT_PROMPT(projectText);
  const initText = await sendMessageWithRetry(session, initPrompt);
  onStepComplete('init', initText || "Modo Auditor Ativado");

  // 2. Criteria 1
  const c1Text = await sendMessageWithRetry(session, PROMPT_CRITERIA_1);
  onStepComplete('criteria1', c1Text || "Critério 1 Analisado");

  // 3. Criteria 2
  const c2Text = await sendMessageWithRetry(session, PROMPT_CRITERIA_2);
  onStepComplete('criteria2', c2Text || "Critério 2 Analisado");

  // 4. Criteria 3
  const c3Text = await sendMessageWithRetry(session, PROMPT_CRITERIA_3);
  onStepComplete('criteria3', c3Text || "Critério 3 Analisado");

  // 5. Final Report
  const finalText = await sendMessageWithRetry(session, PROMPT_FINAL_REPORT);
  onStepComplete('final', finalText || "Relatório Gerado");

  return finalText;
};

