import React, { useState } from 'react';
import { ProjectAnalysis, AnalysisStage, AnalysisStep } from './types';
import { extractTextFromPdf } from './services/pdfService';
import { createAuditSession, runAuditSequence } from './services/geminiService';
import ProjectCard from './components/ProjectCard';

const App: React.FC = () => {
  const [stage, setStage] = useState<AnalysisStage>(AnalysisStage.IDLE);
  const [projects, setProjects] = useState<ProjectAnalysis[]>([]);
  const [progress, setProgress] = useState({ current: 0, total: 0 });

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      alert('Por favor, envie um arquivo PDF válido.');
      return;
    }

    setStage(AnalysisStage.PROCESSING);
    setProjects([]);

    try {
      // 1. Extract Pages
      const pages = await extractTextFromPdf(file);

      const initialProjects: ProjectAnalysis[] = pages.map(p => ({
        pageNumber: p.pageNumber,
        rawText: p.text,
        status: 'pending',
        currentStepIndex: 0,
        steps: [
            { id: 'init', label: 'Inicializando Auditoria', status: 'pending' },
            { id: 'criteria1', label: 'Critério 1: Impacto Social', status: 'pending' },
            { id: 'criteria2', label: 'Critério 2: Viabilidade', status: 'pending' },
            { id: 'criteria3', label: 'Critério 3: Capacidade', status: 'pending' },
            { id: 'final', label: 'Cálculo de Prioridade e Relatório', status: 'pending' },
        ]
      }));

      setProjects(initialProjects);
      setProgress({ current: 0, total: initialProjects.length });

      // 2. Process Sequentially
      await processProjects(initialProjects);

    } catch (error) {
      console.error("Critical Error:", error);
      alert("Falha ao processar o PDF. Tente novamente.");
      setStage(AnalysisStage.IDLE);
    }
  };

  const processProjects = async (initialProjects: ProjectAnalysis[]) => {
    // We create a local copy to update state accurately
    let currentList = [...initialProjects];

    for (let i = 0; i < currentList.length; i++) {
        const projectIndex = i;
        setProgress({ current: i + 1, total: currentList.length });

        // Update status to analyzing
        currentList = updateProjectState(currentList, projectIndex, { status: 'analyzing' });
        setProjects([...currentList]);

        try {
            const session = createAuditSession();

            // Define callback to update UI during the 5 steps
            const onStepComplete = (stepId: string, response: string) => {
                setProjects(prevProjects => {
                    const newProjects = [...prevProjects];
                    const p = newProjects[projectIndex];

                    // Mark step as complete
                    const stepIdx = p.steps.findIndex(s => s.id === stepId);
                    if (stepIdx !== -1) {
                        p.steps[stepIdx].status = 'completed';
                        p.steps[stepIdx].response = response;
                        // Start next step loading if exists
                        if (stepIdx + 1 < p.steps.length) {
                             p.steps[stepIdx + 1].status = 'loading';
                             p.currentStepIndex = stepIdx + 1;
                        }
                    }
                    return newProjects;
                });
            };

            // Start first step loading
            setProjects(prev => {
                const copy = [...prev];
                copy[projectIndex].steps[0].status = 'loading';
                return copy;
            });

            // Run the prompt chain
            const finalReport = await runAuditSequence(
                session, 
                currentList[projectIndex].rawText,
                onStepComplete
            );

            // Mark Project Complete
            currentList = updateProjectState(currentList, projectIndex, { 
                status: 'completed',
                finalReport: finalReport
            });
            setProjects([...currentList]);

        } catch (err: any) {
            console.error(`Error analyzing page ${currentList[projectIndex].pageNumber}`, err);
            currentList = updateProjectState(currentList, projectIndex, { 
                status: 'error',
                error: err.message || "Falha na análise da IA"
            });
            setProjects([...currentList]);
        }

        // Add a delay between projects to respect Rate Limits
        if (i < currentList.length - 1) {
            await new Promise(resolve => setTimeout(resolve, 3000));
        }
    }

    setStage(AnalysisStage.COMPLETED);
  };

  const updateProjectState = (list: ProjectAnalysis[], index: number, updates: Partial<ProjectAnalysis>) => {
      const newList = [...list];
      newList[index] = { ...newList[index], ...updates };
      return newList;
  };

  const generateCSV = () => {
    // Headers for Google Sheets
    const headers = [
      "Nome do Projeto",
      "Nota Critério 1 (Social)",
      "Nota Critério 2 (Viabilidade)",
      "Nota Critério 3 (Capacidade)",
      "Média Técnica",
      "Índice Prioridade BV",
      "Veredito",
      "Destaques/Riscos",
      "Relatório Completo"
    ];

    // Regex helpers
    const findValue = (text: string, regex: RegExp) => {
      const match = text.match(regex);
      return match ? match[1].trim().replace(/"/g, '""') : "";
    };

    const rows = projects.map(p => {
      if (!p.finalReport) return "";
      const text = p.finalReport;

      const name = findValue(text, /\*\*NOME DO PROJETO:\*\*\s*(.*)/);
      const c1 = findValue(text, /\* \*\*Critério 1 \(Inclusão\/Social\):\*\* \[?(\d)\]?/);
      const c2 = findValue(text, /\* \*\*Critério 2 \(Viabilidade\):\*\* \[?(\d)\]?/);
      const c3 = findValue(text, /\* \*\*Critério 3 \(Capacidade\):\*\* \[?(\d)\]?/);
      const avg = findValue(text, /\*\*MÉDIA TÉCNICA:\*\*\s*([\d,.]+)/);
      const index = findValue(text, /\*\*ÍNDICE DE PRIORIDADE BV:\*\*\s*(\d+)/);
      const verdict = findValue(text, /\*\*VEREDITO:\*\*\s*(.*)/);
      const highlights = findValue(text, /\*\*Destaque de Alinhamento:\*\*\s*(.*)/);

      // Escape the full report for CSV cell
      const fullReport = text.replace(/"/g, '""');

      // Use semicolon for Brazilian locale compatibility
      return `"${name}";"${c1}";"${c2}";"${c3}";"${avg}";"${index}";"${verdict}";"${highlights}";"${fullReport}"`;
    });

    // Combine with BOM for Excel/Sheets UTF-8 compatibility
    const csvContent = "\uFEFF" + [headers.join(";"), ...rows].join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'Relatorio_Auditoria_BV.csv';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Header */}
      <header className="bg-bv-dark text-white shadow-lg sticky top-0 z-50">
        <div className="container mx-auto px-6 py-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
                <i className="fas fa-robot text-bv-primary text-2xl"></i>
                <div>
                    <h1 className="text-xl font-bold tracking-tight">Auditor de Projetos BV</h1>
                    <p className="text-xs text-gray-400">Análise Automatizada de Investimento Social</p>
                </div>
            </div>
            {stage === AnalysisStage.PROCESSING && (
                <div className="bg-gray-800 px-4 py-2 rounded-lg flex items-center gap-3 border border-gray-700">
                    <div className="w-4 h-4 border-2 border-bv-primary border-t-transparent rounded-full animate-spin"></div>
                    <span className="text-sm font-medium">Processando Projeto {progress.current} de {progress.total}</span>
                </div>
            )}
            {stage === AnalysisStage.COMPLETED && (
                 <button 
                 onClick={generateCSV}
                 className="bg-green-600 hover:bg-green-700 text-white font-bold py-2 px-4 rounded shadow transition-colors flex items-center gap-2 text-sm"
               >
                 <i className="fas fa-file-excel"></i> Baixar Planilha (.csv)
               </button>
            )}
        </div>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-6 py-8 flex-grow">

        {stage === AnalysisStage.IDLE && (
            <div className="max-w-2xl mx-auto mt-20 text-center">
                <div className="bg-white p-10 rounded-2xl shadow-xl border border-gray-100">
                    <div className="w-20 h-20 bg-blue-50 text-bv-blue rounded-full flex items-center justify-center mx-auto mb-6 text-3xl">
                        <i className="fas fa-file-pdf"></i>
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800 mb-2">Upload de Portfólio de Projetos</h2>
                    <p className="text-gray-500 mb-8">
                        Envie o arquivo PDF contendo os slides dos projetos. A IA irá auditar cada página válida individualmente baseada na Matriz de Critérios Qualitativos do BV.
                    </p>

                    <label className="relative inline-flex items-center justify-center group cursor-pointer">
                        <div className="absolute transition-all duration-200 rounded-full -inset-px bg-gradient-to-r from-cyan-400 to-blue-600 group-hover:opacity-70 opacity-0 blur-lg"></div>
                        <input 
                            type="file" 
                            accept="application/pdf" 
                            onChange={handleFileUpload}
                            className="hidden" 
                        />
                        <div className="relative bg-bv-blue hover:bg-blue-900 text-white font-semibold py-4 px-8 rounded-full shadow-lg transition-all flex items-center gap-3 text-lg">
                            <i className="fas fa-upload"></i>
                            Selecionar Arquivo PDF
                        </div>
                    </label>
                    <p className="mt-4 text-xs text-gray-400">Páginas 1, 2, 14 e 24 serão automaticamente ignoradas.</p>
                </div>
            </div>
        )}

        {(stage === AnalysisStage.PROCESSING || stage === AnalysisStage.COMPLETED) && (
            <div className="max-w-4xl mx-auto">
                <div className="flex justify-between items-end mb-6">
                    <h2 className="text-xl font-bold text-gray-800 border-l-4 border-bv-primary pl-3">
                        Resultados da Auditoria
                    </h2>
                    {stage === AnalysisStage.PROCESSING && (
                        <span className="text-sm text-gray-500 animate-pulse">
                            A IA está analisando com rigor técnico...
                        </span>
                    )}
                </div>

                <div className="space-y-4">
                    {projects.map((project, idx) => (
                        <ProjectCard key={idx} project={project} />
                    ))}
                </div>
            </div>
        )}
      </main>

       {/* Footer */}
       <footer className="bg-white border-t border-gray-200 py-6 mt-8">
            <div className="container mx-auto px-6 text-center text-gray-400 text-sm">
                <p>&copy; {new Date().getFullYear()} Sistema Auditor IA. Uso Interno.</p>
                <p className="text-xs mt-1">Powered by Gemini 2.5 Flash</p>
