interface Props {
  project: ProjectAnalysis;
}

const ProjectCard: React.FC<Props> = ({ project }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  // Extract data from the final report using Regex
  const extractData = (text?: string) => {
    if (!text) return { score: null, name: null, average: null };

    // Extract Index
    const scoreMatch = text.match(/ÍNDICE DE PRIORIDADE BV:\*\*\s*(\d+)/i);
    const score = scoreMatch ? parseInt(scoreMatch[1]) : null;

    // Extract Name
    const nameMatch = text.match(/\*\*NOME DO PROJETO:\*\*\s*(.*)/i);
    const name = nameMatch ? nameMatch[1].trim() : "Projeto não identificado";

    // Extract Average
    const avgMatch = text.match(/\*\*MÉDIA TÉCNICA:\*\*\s*([\d,.]+)/i);
    const average = avgMatch ? avgMatch[1].trim() : "N/A";

    return { score, name, average };
  };

  const { score, name, average } = extractData(project.finalReport);
  const isFinished = project.status === 'completed';
  const isAnalyzing = project.status === 'analyzing';

  const getStatusColor = () => {
    if (project.status === 'error') return 'border-red-500 bg-red-50';
    if (isAnalyzing) return 'border-blue-500 bg-blue-50';
    if (!isFinished) return 'border-gray-200 bg-white';

    // Score based coloring
    if (score !== null) {
      if (score >= 70) return 'border-green-500 bg-white';
      if (score >= 40) return 'border-yellow-500 bg-white';
      return 'border-red-400 bg-white';
    }
    return 'border-gray-200 bg-white';
  };

  return (
    <div className={`border-l-4 rounded-lg shadow-sm mb-4 transition-all duration-300 ${getStatusColor()}`}>
      <div 
        className="p-4 cursor-pointer flex flex-col sm:flex-row gap-4 sm:justify-between sm:items-center"
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="flex items-center gap-4 flex-1">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white shrink-0 ${
                project.status === 'completed' ? (score && score > 60 ? 'bg-green-600' : 'bg-yellow-600') : 'bg-gray-400'
            }`}>
                {project.pageNumber}
            </div>
            <div className="overflow-hidden">
                <h3 className="font-semibold text-lg text-gray-800 truncate">
                    {isFinished ? name : `Projeto (Página ${project.pageNumber})`}
                </h3>
                {!isFinished && (
                  <p className="text-xs text-gray-500 truncate max-w-md">
                    {project.rawText.substring(0, 80)}...
                  </p>
                )}
            </div>
        </div>

        <div className="flex items-center justify-between sm:justify-end gap-3 sm:gap-6 w-full sm:w-auto mt-2 sm:mt-0">
            {isAnalyzing && (
                <div className="flex flex-col items-end flex-1 sm:flex-none">
                     <span className="text-xs font-semibold text-blue-600 animate-pulse">Analisando Etapa {project.currentStepIndex + 1}/5</span>
                     <div className="w-24 h-1 bg-gray-200 rounded-full mt-1">
                        <div 
                            className="h-full bg-blue-600 rounded-full transition-all duration-500"
                            style={{ width: `${((project.currentStepIndex + 1) / 5) * 100}%` }}
                        ></div>
                     </div>
                </div>
            )}
            {isFinished && (
              <div className="flex gap-2 sm:gap-4 items-center">
                 {average && (
                    <div className="flex flex-col items-center p-2 bg-gray-50 border border-gray-200 rounded shadow-sm min-w-[80px]">
                      <span className="text-[10px] text-gray-500 uppercase font-bold tracking-wider">Média Téc.</span>
                      <span className="text-lg font-bold text-blue-900">{average}</span>
                    </div>
                 )}
                 {score !== null && (
                    <div className={`flex flex-col items-center p-2 border rounded shadow-sm min-w-[80px] ${
                        score >= 70 ? 'bg-green-50 border-green-200' : 
                        score >= 40 ? 'bg-yellow-50 border-yellow-200' : 'bg-red-50 border-red-200'
                    }`}>
                        <span className="text-[10px] uppercase font-bold tracking-wider opacity-70">Índice BV</span>
                        <span className={`text-lg font-bold ${
                            score >= 70 ? 'text-green-800' : 
                            score >= 40 ? 'text-yellow-800' : 'text-red-800'
                        }`}>{score}</span>
                    </div>
                 )}
              </div>
            )}
             <i className={`fas fa-chevron-down text-gray-400 transition-transform ml-2 ${isExpanded ? 'rotate-180' : ''}`}></i>
        </div>
      </div>

      {isExpanded && (
        <div className="p-4 border-t border-gray-100 bg-white rounded-b-lg">
            {project.error && (
                <div className="p-3 bg-red-100 text-red-700 rounded mb-4">
                    Erro: {project.error}
                </div>
            )}

            {project.finalReport ? (
                <div className="prose prose-sm max-w-none prose-headings:text-bv-blue">
                    <pre className="whitespace-pre-wrap font-sans text-sm text-gray-700 leading-relaxed">
                        {project.finalReport}
                    </pre>
                </div>
            ) : (
                <div className="space-y-2">
                    <p className="text-sm font-semibold text-gray-500 mb-2">Log de Análise:</p>
                    {project.steps.map((step) => (
                        <div key={step.id} className="flex items-start gap-2 text-sm">
                            <span className={`w-2 h-2 rounded-full mt-1.5 flex-shrink-0 ${
                                step.status === 'completed' ? 'bg-green-500' : 
                                step.status === 'loading' ? 'bg-blue-500 animate-ping' : 'bg-gray-300'
                            }`}></span>
                            <div className="flex-1">
                                <span className="font-medium text-gray-700">{step.label}</span>
                                {step.response && step.status === 'completed' && step.id !== 'final' && (
                                    <div className="text-xs text-gray-500 mt-1 pl-2 border-l-2 border-gray-200">
                                        {step.response.substring(0, 150)}...
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
      )}
    </div>
  );
};

