import { GoogleGenAI } from "@google/genai";
import { FULL_AUDIT_PROMPT } from "../constants";

const getClient = () => {
    if (!process.env.API_KEY) {
        throw new Error("API Key is missing. Please set process.env.API_KEY.");
    }
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Executes the full audit in a single request to minimize latency and API calls.
 */
export const runFullAudit = async (projectText: string): Promise<string> => {
    const ai = getClient();
    const model = 'gemini-2.5-flash';
    const prompt = FULL_AUDIT_PROMPT(projectText);

    return await generateContentWithRetry(ai, model, prompt);
};

/**
 * Helper function to send generateContent with retry logic for rate limits (429)
 */
const generateContentWithRetry = async (ai: GoogleGenAI, model: string, prompt: string, retries = 5, baseDelay = 5000): Promise<string> => {
    for (let i = 0; i < retries; i++) {
        try {
            const response = await ai.models.generateContent({
                model: model,
                contents: prompt,
                config: {
                    temperature: 0.2,
                    candidateCount: 1,
                }
            });
            return response.text || "";
        } catch (error: any) {
            const isRateLimit = 
                error.status === 429 || 
                error.code === 429 || 
                (error.message && error.message.includes('429')) ||
                (error.message && error.message.toLowerCase().includes('quota')) ||
                (error.message && error.message.toLowerCase().includes('resource_exhausted'));

            const isServerIssue = error.status === 503 || error.code === 503;

            if ((isRateLimit || isServerIssue) && i < retries - 1) {
                const waitTime = baseDelay * Math.pow(2, i); 
                console.warn(`Limite de taxa atingido (429/503). Tentativa ${i + 1}/${retries}. Aguardando ${waitTime/1000}s...`);
                await new Promise(resolve => setTimeout(resolve, waitTime));
                continue;
            }
            throw error;
        }
    }
    throw new Error("Número máximo de tentativas excedido devido a limites da API.");
};

import React, { useState } from 'react';
import { ProjectAnalysis, AnalysisStage } from './types';
