import * as pdfjsLib from 'pdfjs-dist';
import { PdfPage } from '../types';

// Set the worker source for pdfjs-dist
pdfjsLib.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${pdfjsLib.version}/build/pdf.worker.min.mjs`;

/**
 * Extracts text from a single file.
 */
export const extractTextFromPdf = async (file: File): Promise<string> => {
  const pages = await processPdfFile(file);
  return pages.map(p => p.text).join('\n');
};

/**
 * Extracts text from multiple files, adding headers to identify the source file.
 * This is crucial for the AI to distinguish between the "Bylaws" and the "Project Form".
 */
export const extractTextFromMultipleFiles = async (files: File[]): Promise<string> => {
  let combinedText = "";

  for (const file of files) {
    try {
      const pages = await processPdfFile(file);
      const fileText = pages.map(p => p.text).join('\n');

      combinedText += `\n\n=== INÍCIO DO ARQUIVO: ${file.name} ===\n`;
      combinedText += fileText;
      combinedText += `\n=== FIM DO ARQUIVO: ${file.name} ===\n`;
    } catch (error) {
      console.error(`Error processing file ${file.name}:`, error);
      combinedText += `\n\n[ERRO AO LER O ARQUIVO: ${file.name}]\n\n`;
    }
  }

  return combinedText;
};

const processPdfFile = async (file: File): Promise<PdfPage[]> => {
  const arrayBuffer = await file.arrayBuffer();
  const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
  const pdf = await loadingTask.promise;

  const pages: PdfPage[] = [];

  for (let i = 1; i <= pdf.numPages; i++) {
    try {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const text = textContent.items
        .map((item: any) => item.str)
        .join(' ')
        .replace(/\s+/g, ' ') // normalize whitespace
        .trim();

      if (text.length > 20) { 
        pages.push({
          pageNumber: i,
          text: text,
          fileName: file.name
        });
      }
    } catch (error) {
      console.error(`Error processing page ${i} of ${file.name}:`, error);
    }
  }

  return pages;
};

import { GoogleGenAI } from "@google/genai";
import { DOCUMENT_AUDIT_PROMPT } from "../constants";

const getClient = () => {
    if (!process.env.API_KEY) {
        throw new Error("API Key is missing. Please set process.env.API_KEY.");
    }
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const runDocumentAudit = async (
    regulation: string,
    formTemplate: string,
    criteria: string,
    candidateText: string
): Promise<string> => {
    const ai = getClient();
    const model = 'gemini-2.5-flash';

    // Construct the prompt with all context
    const prompt = DOCUMENT_AUDIT_PROMPT(regulation, formTemplate, criteria, candidateText);

    return await generateContentWithRetry(ai, model, prompt);
};

const generateContentWithRetry = async (ai: GoogleGenAI, model: string, prompt: string, retries = 3, baseDelay = 2000): Promise<string> => {
    for (let i = 0; i < retries; i++) {
        try {
            const response = await ai.models.generateContent({
                model: model,
                contents: prompt,
                config: {
                    temperature: 0.1, // Very low temperature for strict compliance checking
                    candidateCount: 1,
                }
            });
            return response.text || "";
        } catch (error: any) {
            const isRateLimit = error.status === 429 || error.message?.includes('429');
            if (isRateLimit && i < retries - 1) {
                const waitTime = baseDelay * Math.pow(2, i);
                await new Promise(resolve => setTimeout(resolve, waitTime));
                continue;
            }
            throw error;
        }
    }
    throw new Error("Falha na comunicação com a IA após múltiplas tentativas.");
};

