                                                        <span className="block font-bold text-gray-400 text-[10px] uppercase mb-1">Evidência Extraída:</span>
                                                        "{point.evidence}"
                                                    </div>

                                                    <p className="text-sm text-gray-700">
                                                        <span className="font-semibold text-gray-900">Análise: </span>
                                                        {point.justification}
                                                    </p>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </div>
        )}

      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-gray-200 mt-auto py-6">
        <div className="container mx-auto px-6 flex justify-center text-xs text-gray-400">
            <span>&copy; {new Date().getFullYear()} Prosas. Todos os direitos reservados.</span>
        </div>
      </footer>
    </div>
  );
};

