import React, { useState } from 'react';
import { CandidateAnalysis, AppStage, AuditContext, AnalysisPoint } from './types';
import { extractTextFromPdf } from './services/pdfService';
import { runDocumentAudit } from './services/geminiService';
import { DEFAULT_DOCUMENT_CRITERIA } from './constants';

const App: React.FC = () => {
  const [stage, setStage] = useState<AppStage>(AppStage.SETUP);
  const [loading, setLoading] = useState(false);

  // Context State
  const [context, setContext] = useState<AuditContext>({
    editalTitle: '',
    regulationText: '',
    formTemplateText: '',
    miscFilesText: '',
    criteriaText: DEFAULT_DOCUMENT_CRITERIA,
    isReady: false
  });

  // Candidate State
  const [candidate, setCandidate] = useState<CandidateAnalysis | null>(null);

  // Handlers for Context Uploads
  const handleContextUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'regulation' | 'form' | 'misc') => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    try {
        const text = await extractTextFromPdf(file);
        setContext(prev => {
            const newContext = { ...prev };
            if (type === 'regulation') {
                newContext.regulationText = text;
                // Try to extract a title from the first line, otherwise generic
                // Increased limit from 50 to 150 chars to avoid cutting off titles like "... - 2025"
                const firstLine = text.split('\n')[0]?.substring(0, 150);
                newContext.editalTitle = firstLine && firstLine.length > 5 ? firstLine : "Edital Carregado";
            }
            if (type === 'form') newContext.formTemplateText = text;
            if (type === 'misc') newContext.miscFilesText = text;
            return newContext;
        });
    } catch (err) {
        alert("Erro ao ler arquivo: " + err);
    } finally {
        setLoading(false);
    }
  };

  const finishSetup = () => {
      setStage(AppStage.AUDIT);
  };

  // Handlers for Candidate Analysis
  const handleCandidateUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!e.target.files || e.target.files.length === 0) return;

      const files = Array.from(e.target.files);
      setLoading(true);

      try {
        // Create candidate object immediately
        const newCandidate: CandidateAnalysis = {
            id: Date.now().toString(),
            candidateName: "Processando...",
            files: files,
            rawText: "",
            status: 'analyzing'
        };
        setCandidate(newCandidate);

        // Run Audit
        const result = await runDocumentAudit(
            context.regulationText,
            context.formTemplateText,
            context.miscFilesText,
            context.criteriaText,
            files
        );

        // Update result
        setCandidate({
            ...newCandidate,
            status: 'completed',
            result: result,
            candidateName: result.candidateName || "Candidato Identificado"
        });

      } catch (err: any) {
          setCandidate(prev => prev ? ({ ...prev, status: 'error', error: err.message }) : null);
      } finally {
          setLoading(false);
      }
