          case 'ERROR': return <span className="bg-red-100 text-red-800 text-xs font-bold px-2 py-1 rounded border border-red-200">IRREGULAR</span>;
          case 'WARNING': return <span className="bg-yellow-100 text-yellow-800 text-xs font-bold px-2 py-1 rounded border border-yellow-200">RESSALVA</span>;
