  });

  // Slots State: Fixed array of 3 slots. null means empty.
  const [candidates, setCandidates] = useState<(CandidateAnalysis | null)[]>([null, null, null]);

  // Handlers for Context Uploads
  const handleContextUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'regulation' | 'form' | 'misc') => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoadingContext(true);
    try {
        const text = await extractTextFromPdf(file);
        setContext(prev => {
            const newContext = { ...prev };
            if (type === 'regulation') {
                newContext.regulationText = text;
                const firstLine = text.split('\n')[0]?.substring(0, 150);
                newContext.editalTitle = firstLine && firstLine.length > 5 ? firstLine : "Edital Carregado";
            }
            if (type === 'form') newContext.formTemplateText = text;
            if (type === 'misc') newContext.miscFilesText = text;
            return newContext;
        });
    } catch (err) {
        alert("Erro ao ler arquivo: " + err);
    } finally {
        setLoadingContext(false);
    }
  };

  const finishSetup = () => {
      setStage(AppStage.AUDIT);
  };

  // Handler for specific slot upload
  const handleSlotUpload = async (e: React.ChangeEvent<HTMLInputElement>, slotIndex: number) => {
      if (!e.target.files || e.target.files.length === 0) return;

      const files = Array.from(e.target.files);

      // Initialize slot state
      setCandidates(prev => {
          const newSlots = [...prev];
          newSlots[slotIndex] = {
              slotId: slotIndex,
              id: Date.now().toString(),
              candidateName: "Iniciando análise...",
              files: files,
              rawText: "",
              status: 'analyzing'
          };
          return newSlots;
      });

      try {
        // Run Audit for this specific slot
        const result = await runDocumentAudit(
            context.regulationText,
            context.formTemplateText,
            context.miscFilesText,
            context.criteriaText,
            files
        );

        // Update slot with result
        setCandidates(prev => {
            const newSlots = [...prev];
            if (newSlots[slotIndex]) {
                newSlots[slotIndex] = {
                    ...newSlots[slotIndex]!,
                    status: 'completed',
                    result: result,
                    candidateName: result.candidateName || "Candidato Identificado"
                };
            }
            return newSlots;
        });

      } catch (err: any) {
          setCandidates(prev => {
            const newSlots = [...prev];
            if (newSlots[slotIndex]) {
                newSlots[slotIndex] = { ...newSlots[slotIndex]!, status: 'error', error: err.message };
            }
            return newSlots;
          });
      }
  };

  const clearSlot = (slotIndex: number) => {
      setCandidates(prev => {
          const newSlots = [...prev];
          newSlots[slotIndex] = null;
          return newSlots;
      });
  };

  // Helper to render status badge
  const renderStatusBadge = (status: string) => {
      switch(status) {
          case 'OK': return <span className="bg-green-100 text-green-800 text-[10px] font-bold px-2 py-0.5 rounded border border-green-200">CONFORME</span>;
          case 'ERROR': return <span className="bg-red-100 text-red-800 text-[10px] font-bold px-2 py-0.5 rounded border border-red-200">IRREGULAR</span>;
          case 'WARNING': return <span className="bg-yellow-100 text-yellow-800 text-[10px] font-bold px-2 py-0.5 rounded border border-yellow-200">RESSALVA</span>;
          default: return null;
      }
  };

  return (
    <div className="min-h-screen bg-prosas-bg flex flex-col font-sans text-slate-800">

      {/* Prosas Header */}
      <header className="bg-prosas-red text-white shadow-md sticky top-0 z-50 h-16">
        <div className="container mx-auto px-4 h-full flex justify-between items-center">
            <div className="flex items-center gap-2">
                 <span className="text-2xl font-bold italic tracking-tight">prosas</span>
            </div>
            <div className="flex flex-col items-center max-w-lg text-center overflow-hidden">
                 <span className="text-xs font-semibold uppercase tracking-wider opacity-80">Ambiente de Auditoria</span>
                 <span className="font-bold truncate w-full">
                    {context.editalTitle ? context.editalTitle : "Configuração Inicial"}
                 </span>
            </div>
            <div className="w-20"></div>
        </div>
      </header>

      {/* Breadcrumb */}
      <div className="bg-white border-b border-gray-200 py-3 shadow-sm">
         <div className="container mx-auto px-6 flex items-center text-sm text-gray-600">
             <span className={`${stage === AppStage.SETUP ? 'font-bold text-prosas-blue' : ''}`}>1. Parâmetros</span>
             <i className="fas fa-chevron-right mx-3 text-xs text-gray-400"></i>
             <span className={`${stage === AppStage.AUDIT ? 'font-bold text-prosas-blue' : ''}`}>2. Análise Documental (Múltipla)</span>

             {stage === AppStage.AUDIT && (
                <button onClick={() => setStage(AppStage.SETUP)} className="ml-auto text-xs text-prosas-blue hover:underline">
                    <i className="fas fa-cog mr-1"></i> Configurar Edital
                </button>
             )}
         </div>
      </div>

      <main className="container mx-auto px-4 py-8 flex-grow">

        {/* STAGE 1: SETUP */}
        {stage === AppStage.SETUP && (
            <div className="max-w-6xl mx-auto animate-fade-in">
                {/* ... (Existing Setup Code remains mostly same, just slightly compacted for brevity in XML if needed, but keeping logic) ... */}
                 <div className="flex items-center gap-3 mb-6">
                    <div className="p-2 bg-blue-100 text-prosas-blue rounded-lg">
                        <i className="fas fa-sliders-h text-xl"></i>
                    </div>
                    <div>
                        <h2 className="text-xl font-bold text-gray-800">Parâmetros de Análise</h2>
                        <p className="text-sm text-gray-500">Carregue o regulamento para definir o contexto da auditoria.</p>
                    </div>
                </div>

                <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
                    {/* Regulation Upload */}
                    <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                        <h3 className="font-bold text-gray-700 mb-2 flex items-center gap-2">
                            <i className="fas fa-book text-prosas-red"></i> 1. Regulamento
                        </h3>
                        <label className="block w-full cursor-pointer hover:bg-gray-50 transition p-6 border-2 border-dashed border-gray-300 rounded text-center group">
                            <input type="file" accept="application/pdf" className="hidden" onChange={(e) => handleContextUpload(e, 'regulation')} />
                            {context.regulationText ? (
                                <div className="text-green-600 font-bold flex flex-col items-center">
