                                                            {candidate.result.organizationData.legalStatus}
                                                        </span>
                                                    </div>
                                                    <div className="col-span-2">
                                                        <span className="block text-gray-500 text-[9px] uppercase">Representante</span>
                                                        <span className="font-bold text-gray-700">{candidate.result.organizationData.representativeName}</span>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Overall Status */}
                                            <div className={`p-4 rounded border-l-4 ${
                                                candidate.result.overallStatus === 'APROVADO' ? 'bg-green-50 border-green-500' : 
                                                candidate.result.overallStatus === 'REPROVADO' ? 'bg-red-50 border-red-500' : 'bg-yellow-50 border-yellow-500'
                                            }`}>
                                                <div className={`text-xl font-bold mb-2 ${
                                                    candidate.result.overallStatus === 'APROVADO' ? 'text-green-700' : 
                                                    candidate.result.overallStatus === 'REPROVADO' ? 'text-red-700' : 'text-yellow-700'
                                                }`}>
                                                    {candidate.result.overallStatus}
                                                </div>
                                                <p className="text-xs text-gray-700 whitespace-pre-wrap leading-relaxed">
                                                    {candidate.result.summary}
                                                </p>
                                            </div>

                                            {/* Points */}
                                            <div className="space-y-3">
                                                {candidate.result.points.map((point, idx) => (
                                                    <div key={idx} className="bg-white rounded border border-gray-200 p-3 hover:shadow-sm">
                                                        <div className="flex justify-between items-start mb-2 gap-2">
                                                            <h5 className="font-bold text-xs text-gray-800 leading-tight">{point.title}</h5>
                                                            {renderStatusBadge(point.status)}
                                                        </div>
                                                        <div className="bg-gray-100 p-2 rounded text-[10px] text-gray-600 font-mono mb-2 border-l-2 border-gray-300">
                                                            "{point.evidence}"
                                                        </div>
                                                        <p className="text-[11px] text-gray-700 leading-snug">
                                                            {point.justification}
                                                        </p>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>
                ))}
            </div>
        )}

      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-gray-200 mt-auto py-4">
        <div className="container mx-auto px-6 flex justify-center text-[10px] text-gray-400">
            <span>&copy; {new Date().getFullYear()} Prosas. Todos os direitos reservados.</span>
        </div>
      </footer>
    </div>
  );
};

