                                                    <p className="text-xs text-gray-500 mb-6 px-4 line-clamp-3">{candidate.result.summary}</p>

                                                    <button 
                                                        onClick={() => { setSelectedReport({
                                                            id: candidate.id,
                                                            editalName: context.editalTitle,
                                                            candidateName: candidate.candidateName,
                                                            cnpj: candidate.result!.organizationData.cnpj,
                                                            timestamp: Date.now(),
                                                            result: candidate.result!
                                                        }); setStage(AppStage.REPORT_VIEW); }}
                                                        className="w-full border border-gray-300 hover:border-prosas-blue text-gray-600 font-bold py-2 rounded text-sm transition-colors"
                                                    >
                                                        Ver Relatório Completo
                                                    </button>
                                                </div>
                                            )}
                                            {candidate.status === 'error' && (
                                                <div className="text-center text-red-600 p-4">
                                                    <i className="fas fa-exclamation-triangle text-2xl mb-2"></i>
                                                    <p className="text-sm">{candidate.error}</p>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                   </div>
               </div>
          )}

      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { CandidateAnalysis } from '../types';

interface Props {
  project: CandidateAnalysis;
  index?: number;
}

const ProjectCard: React.FC<Props> = ({ project, index = 0 }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const isFinished = project.status === 'completed';
  const isAnalyzing = project.status === 'analyzing';
  const result = project.result;

  const getStatusColor = () => {
    if (project.status === 'error') return 'border-red-500 bg-red-50';
    if (isAnalyzing) return 'border-prosas-blue bg-blue-50';
    if (!isFinished) return 'border-gray-200 bg-white';

    // Status based coloring
    if (result?.overallStatus === 'APROVADO') return 'border-green-500 bg-white';
    if (result?.overallStatus === 'REPROVADO') return 'border-red-400 bg-white';
    return 'border-yellow-500 bg-white';
  };

  return (
    <div className={`border-l-4 rounded shadow-sm mb-4 transition-all duration-300 ${getStatusColor()}`}>
      <div 
        className="p-4 cursor-pointer flex flex-col sm:flex-row gap-4 sm:justify-between sm:items-center"
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="flex items-center gap-4 flex-1">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-white shrink-0 ${
                project.status === 'completed' 
                  ? (result?.overallStatus === 'APROVADO' ? 'bg-green-600' : result?.overallStatus === 'REPROVADO' ? 'bg-red-600' : 'bg-yellow-600') 
                  : 'bg-gray-400'
            }`}>
                {index + 1}
            </div>
            <div className="overflow-hidden">
                <h3 className="font-semibold text-lg text-gray-800 truncate">
                    {project.candidateName || "Candidato"}
                </h3>
                {!isFinished && project.files && (
                  <p className="text-xs text-gray-500 truncate max-w-md">
                    {project.files.map((f: File) => f.name).join(', ')}
                  </p>
                )}
            </div>
        </div>

        <div className="flex items-center justify-between sm:justify-end gap-3 sm:gap-6 w-full sm:w-auto mt-2 sm:mt-0">
            {isAnalyzing && (
                <div className="flex flex-col items-end flex-1 sm:flex-none">
                     <span className="text-xs font-semibold text-prosas-blue animate-pulse">Analisando...</span>
                </div>
            )}
            {isFinished && result && (
              <div className="flex gap-2 sm:gap-4 items-center">
                 <div className={`px-2 py-1 rounded text-xs font-bold ${
                    result.overallStatus === 'APROVADO' ? 'bg-green-100 text-green-700' :
                    result.overallStatus === 'REPROVADO' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'
                 }`}>
                    {result.overallStatus}
                 </div>
              </div>
            )}
             <i className={`fas fa-chevron-down text-gray-400 transition-transform ml-2 ${isExpanded ? 'rotate-180' : ''}`}></i>
        </div>
      </div>

      {isExpanded && (
        <div className="p-4 border-t border-gray-100 bg-white rounded-b-lg">
            {project.error && (
                <div className="p-3 bg-red-100 text-red-700 rounded mb-4">
                    Erro: {project.error}
                </div>
            )}

            {result && (
                <div className="space-y-4">
                    <div className="text-sm text-gray-700">
                      <span className="font-bold">Resumo:</span> {result.summary}
                    </div>
                     <div className="space-y-2">
                        {result.points.map((point, idx) => (
                            <div key={idx} className="flex items-start gap-2 text-sm border-b border-gray-50 pb-2 last:border-0">
                                <span className={`shrink-0 w-2 h-2 rounded-full mt-1.5 ${
                                    point.status === 'OK' ? 'bg-green-500' : 
                                    point.status === 'ERROR' ? 'bg-red-500' : 'bg-yellow-500'
                                }`}></span>
                                <div className="flex-1">
                                    <span className="font-medium text-gray-700">{point.title}</span>
                                    <p className="text-xs text-gray-500">{point.justification}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
      )}
    </div>
  );
};

