                                              report.result.overallStatus === 'APROVADO' ? 'bg-green-100 text-green-700' :
                                              report.result.overallStatus === 'REPROVADO' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'
                                          }`}>
                                              <span className={`w-1.5 h-1.5 rounded-full ${
                                                  report.result.overallStatus === 'APROVADO' ? 'bg-green-500' :
                                                  report.result.overallStatus === 'REPROVADO' ? 'bg-red-500' : 'bg-yellow-500'
                                              }`}></span>
                                              {report.result.overallStatus}
