                                }`}
                            >
                                Avançar <i className="fas fa-arrow-right"></i>
                            </button>
                        </div>
                   </div>
               </div>
          )}

          {/* VIEW: RUNNER */}
          {stage === AppStage.ANALYSIS_RUN && (
               <div className="max-w-[1600px] mx-auto animate-fade-in">
                   <div className="flex items-center justify-between mb-8">
                       <div className="flex items-center gap-4">
                           <button onClick={() => setStage(AppStage.ANALYSIS_SETUP)} className="w-10 h-10 rounded-full bg-white border border-gray-200 flex items-center justify-center text-gray-500 hover:text-prosas-blue transition-colors">
                               <i className="fas fa-arrow-left"></i>
                           </button>
                           <div>
                                <h1 className="text-2xl font-bold text-gray-800">Upload de Projetos</h1>
                                <p className="text-sm text-gray-500">Edital Ativo: <strong>{context.editalTitle}</strong></p>
                           </div>
                       </div>
                   </div>

                   <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                        {candidates.map((candidate, index) => (
                            <div key={index} className="flex flex-col h-full min-h-[500px]">
                                {!candidate ? (
                                    <div className="bg-white p-8 rounded-lg shadow-sm border-2 border-dashed border-gray-300 hover:border-prosas-blue transition-colors flex flex-col items-center justify-center text-center h-full">
                                        <div className="w-14 h-14 bg-gray-50 text-gray-400 rounded-full flex items-center justify-center mb-4 text-xl font-bold">
                                            {index + 1}
                                        </div>
                                        <h3 className="text-lg font-bold text-gray-700 mb-2">Slot Disponível</h3>
                                        <label className="cursor-pointer bg-prosas-blue hover:bg-prosas-blueDark text-white font-bold py-3 px-6 rounded shadow transition-all flex items-center gap-2 text-sm uppercase tracking-wide mt-4">
                                            <input type="file" accept="application/pdf" multiple onChange={(e) => handleSlotUpload(e, index)} className="hidden" />
                                            <i className="fas fa-upload"></i> Carregar Projeto
                                        </label>
                                    </div>
                                ) : (
                                    <div className="bg-white rounded-lg shadow-md border border-gray-200 flex flex-col h-full overflow-hidden relative">
                                        {/* Simplified Card for Runner View */}
                                        <div className="p-4 border-b border-gray-100 flex justify-between items-start bg-gray-50">
                                            <div>
                                                 <span className={`text-[10px] font-bold px-2 py-0.5 rounded mb-1 inline-block ${
                                                     candidate.status === 'completed' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'
                                                 }`}>
                                                     {candidate.status === 'completed' ? 'FINALIZADO' : 'EM ANÁLISE'}
                                                 </span>
                                                 <h3 className="font-bold text-gray-800 text-sm truncate w-64">{candidate.candidateName}</h3>
                                            </div>
                                            <button onClick={() => clearSlot(index)} className="text-gray-400 hover:text-red-500"><i className="fas fa-trash"></i></button>
                                        </div>

                                        <div className="p-6 flex-grow flex flex-col items-center justify-center">
                                            {candidate.status === 'analyzing' && (
                                                <>
                                                    <div className="w-12 h-12 border-4 border-prosas-blue border-t-transparent rounded-full animate-spin mb-4"></div>
                                                    <p className="text-sm text-gray-500">A IA está auditando os documentos...</p>
                                                </>
                                            )}
                                            {candidate.status === 'completed' && candidate.result && (
                                                <div className="text-center w-full">
                                                    <div className={`w-16 h-16 rounded-full flex items-center justify-center text-2xl mx-auto mb-4 ${
                                                        candidate.result.overallStatus === 'APROVADO' ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'
                                                    }`}>
                                                        <i className={`fas ${candidate.result.overallStatus === 'APROVADO' ? 'fa-check' : 'fa-times'}`}></i>
                                                    </div>
                                                    <h3 className="font-bold text-lg mb-2">{candidate.result.overallStatus}</h3>
                                                    <p className="text-xs text-gray-500 mb-6 px-4 line-clamp-3">{candidate.result.summary}</p>

                                                    <button 
                                                        onClick={() => { setSelectedReport({
                                                            id: candidate.id,
                                                            editalName: context.editalTitle,
                                                            candidateName: candidate.candidateName,
                                                            cnpj: candidate.result!.organizationData.cnpj,
                                                            timestamp: Date.now(),
                                                            result: candidate.result!
                                                        }); setStage(AppStage.REPORT_VIEW); }}
                                                        className="w-full border border-gray-300 hover:border-prosas-blue text-gray-600 font-bold py-2 rounded text-sm transition-colors"
                                                    >
                                                        Ver Relatório Completo
                                                    </button>
                                                </div>
                                            )}
                                            {candidate.status === 'error' && (
                                                <div className="text-center text-red-600 p-4">
                                                    <i className="fas fa-exclamation-triangle text-2xl mb-2"></i>
                                                    <p className="text-sm">{candidate.error}</p>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                   </div>
               </div>
          )}

      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { CandidateAnalysis, AppStage, AuditContext, UserProfile, SavedReport } from './types';
import { extractTextFromPdf } from './services/pdfService';
import { runDocumentAudit } from './services/geminiService';
import { saveReport, getReportsByEdital } from './services/storageService';
import { DEFAULT_DOCUMENT_CRITERIA } from './constants';
import ReportViewer from './components/ReportViewer';

const App: React.FC = () => {
  const [stage, setStage] = useState<AppStage>(AppStage.LOGIN);
  const [user, setUser] = useState<UserProfile | null>(null);

  // Storage & Reports
  const [groupedReports, setGroupedReports] = useState<Record<string, SavedReport[]>>({});
  const [selectedReport, setSelectedReport] = useState<SavedReport | null>(null);

  // Analysis State
  const [loadingContext, setLoadingContext] = useState(false);
  const [context, setContext] = useState<AuditContext>({
    editalTitle: '',
    regulationText: '',
    formTemplateText: '',
    miscFilesText: '',
    criteriaText: DEFAULT_DOCUMENT_CRITERIA,
    isReady: false
  });
  const [candidates, setCandidates] = useState<(CandidateAnalysis | null)[]>([null, null, null]);

  // Load reports on mount or stage change
  useEffect(() => {
    if (stage === AppStage.DASHBOARD) {
      setGroupedReports(getReportsByEdital());
    }
  }, [stage]);

  const handleLocalLogin = () => {
      // Simulação de login local para manter a estrutura do app
      setUser({
          name: "Administrador",
          email: "admin@prosas.local",
          avatarUrl: "https://ui-avatars.com/api/?name=Admin+Prosas&background=C13B2E&color=fff&size=128"
      });
      setStage(AppStage.DASHBOARD);
  };

  const handleLogout = () => {
      setUser(null);
      setStage(AppStage.LOGIN);
  };

  // --- ANALYSIS HANDLERS ---

  const handleContextUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'regulation' | 'form' | 'misc') => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoadingContext(true);
    try {
        const text = await extractTextFromPdf(file);
        setContext(prev => {
            const newContext = { ...prev };
            if (type === 'regulation') {
                newContext.regulationText = text;
                const firstLine = text.split('\n')[0]?.substring(0, 150);
                newContext.editalTitle = firstLine && firstLine.length > 5 ? firstLine : "Novo Edital";
            }
            if (type === 'form') newContext.formTemplateText = text;
            if (type === 'misc') newContext.miscFilesText = text;
            return newContext;
        });
    } catch (err) {
        alert("Erro ao ler arquivo: " + err);
    } finally {
        setLoadingContext(false);
    }
  };

  const handleSlotUpload = async (e: React.ChangeEvent<HTMLInputElement>, slotIndex: number) => {
      if (!e.target.files || e.target.files.length === 0) return;
      const files = Array.from(e.target.files);

      // Init Slot
      setCandidates(prev => {
          const newSlots = [...prev];
          newSlots[slotIndex] = {
              slotId: slotIndex,
              id: Date.now().toString(),
              candidateName: "Iniciando análise...",
              files: files,
              rawText: "",
              status: 'analyzing'
          };
          return newSlots;
      });

      try {
        const result = await runDocumentAudit(
            context.regulationText,
            context.formTemplateText,
            context.miscFilesText,
            context.criteriaText,
            files
        );

        // Save immediately to DB
        const saved = saveReport(context.editalTitle, result);

        // Update Slot
        setCandidates(prev => {
            const newSlots = [...prev];
            if (newSlots[slotIndex]) {
                newSlots[slotIndex] = {
                    ...newSlots[slotIndex]!,
                    status: 'completed',
                    result: result,
                    candidateName: result.candidateName || "Candidato Identificado"
                };
            }
            return newSlots;
        });

      } catch (err: any) {
          setCandidates(prev => {
            const newSlots = [...prev];
            if (newSlots[slotIndex]) {
                newSlots[slotIndex] = { ...newSlots[slotIndex]!, status: 'error', error: err.message };
            }
            return newSlots;
          });
      }
  };

  const clearSlot = (slotIndex: number) => {
      setCandidates(prev => {
          const newSlots = [...prev];
          newSlots[slotIndex] = null;
          return newSlots;
      });
  };

  // --- RENDERERS ---

  if (stage === AppStage.LOGIN) {
      return (
          <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
              <div className="bg-white p-8 rounded-lg shadow-lg max-w-md w-full text-center border-t-4 border-prosas-red">
                  <h1 className="text-3xl font-bold italic text-prosas-red mb-2">prosas</h1>
                  <p className="text-gray-500 mb-8 text-sm">Auditoria de Projetos IA</p>

                  <div className="bg-blue-50 border border-blue-200 rounded p-4 mb-6 text-left">
                      <p className="text-xs text-blue-800 font-bold mb-1"><i className="fas fa-database mr-1"></i> Modo Local Ativo</p>
                      <p className="text-xs text-blue-600">Seus dados e relatórios são salvos apenas neste navegador. Nenhuma informação é compartilhada externamente.</p>
                  </div>

                  <button 
                    onClick={handleLocalLogin}
                    className="w-full bg-prosas-red hover:bg-red-700 text-white font-bold py-3 px-4 rounded flex items-center justify-center gap-3 transition-colors shadow-sm"
                  >
                      Acessar Sistema
                  </button>

                  <p className="text-xs text-gray-400 mt-6 flex items-center justify-center gap-2">
                      <i className="fas fa-lock"></i> Ambiente Seguro
                  </p>
              </div>
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex font-sans text-slate-800">

      {/* SIDEBAR */}
      <aside className="w-64 bg-white border-r border-gray-200 flex-shrink-0 flex flex-col h-screen sticky top-0">
          <div className="p-6 border-b border-gray-100 flex items-center gap-2">
             <span className="text-2xl font-bold italic tracking-tight text-prosas-red">prosas</span>
             <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded font-bold mt-1">AUDIT</span>
          </div>

          <nav className="flex-grow p-4 overflow-y-auto custom-scrollbar">
              <div className="mb-6">
                  <button 
                    onClick={() => setStage(AppStage.ANALYSIS_SETUP)}
                    className="w-full bg-prosas-blue hover:bg-prosas-blueDark text-white font-bold py-3 px-4 rounded shadow-sm transition-all flex items-center justify-center gap-2 text-sm uppercase tracking-wide"
                  >
                      <i className="fas fa-plus"></i> Nova Análise
                  </button>
              </div>

              <div className="mb-2 px-2 text-xs font-bold text-gray-400 uppercase tracking-wider">
                  Histórico por Edital
              </div>

              <div className="space-y-1">
                  <button 
                     onClick={() => { setStage(AppStage.DASHBOARD); setSelectedReport(null); }}
                     className={`w-full text-left px-3 py-2 rounded text-sm flex items-center gap-3 ${stage === AppStage.DASHBOARD ? 'bg-blue-50 text-prosas-blue font-bold' : 'text-gray-600 hover:bg-gray-50'}`}
                  >
                      <i className="fas fa-th-large"></i> Visão Geral
                  </button>

                  {Object.keys(groupedReports).map(editalName => (
                      <div key={editalName} className="mt-4">
                          <div className="px-3 py-1 text-xs font-bold text-gray-500 flex items-center gap-2 truncate" title={editalName}>
                              <i className="fas fa-folder text-yellow-400"></i> {editalName}
                          </div>
                          <div className="ml-4 mt-1 space-y-0.5 border-l-2 border-gray-100 pl-2">
                              {groupedReports[editalName].map(report => (
                                  <button 
                                    key={report.id}
                                    onClick={() => { setSelectedReport(report); setStage(AppStage.REPORT_VIEW); }}
                                    className="w-full text-left px-2 py-1.5 rounded text-xs text-gray-500 hover:text-prosas-blue hover:bg-gray-50 truncate transition-colors flex justify-between items-center group"
                                  >
                                      <span className="truncate">{report.candidateName}</span>
                                      <span className={`w-2 h-2 rounded-full flex-shrink-0 ${
                                          report.result.overallStatus === 'APROVADO' ? 'bg-green-400' : 'bg-red-400'
                                      }`}></span>
                                  </button>
                              ))}
                          </div>
                      </div>
                  ))}
              </div>
          </nav>

          <div className="p-4 border-t border-gray-100">
              <div className="flex items-center gap-3 mb-3">
                  <img src={user?.avatarUrl} alt="User" className="w-8 h-8 rounded-full border border-gray-200" />
                  <div className="overflow-hidden">
                      <p className="text-sm font-bold text-gray-800 truncate" title={user?.name}>{user?.name}</p>
                      <p className="text-xs text-gray-500 truncate" title={user?.email}>{user?.email}</p>
                  </div>
              </div>
              <button 
                  onClick={handleLogout}
                  className="w-full text-xs text-gray-500 hover:text-red-600 flex items-center justify-center gap-2 py-1"
              >
                  <i className="fas fa-sign-out-alt"></i> Sair
              </button>
          </div>
      </aside>

      {/* MAIN CONTENT */}
      <main className="flex-1 overflow-y-auto h-screen bg-gray-50 p-8">

          {/* VIEW: REPORT VIEWER (IDWALL STYLE) */}
          {stage === AppStage.REPORT_VIEW && selectedReport && (
              <ReportViewer report={selectedReport} onBack={() => setStage(AppStage.DASHBOARD)} />
          )}

          {/* VIEW: DASHBOARD */}
          {stage === AppStage.DASHBOARD && (
              <div className="max-w-6xl mx-auto animate-fade-in">
                  <h1 className="text-2xl font-bold text-gray-800 mb-6">Visão Geral das Análises</h1>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                      <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                          <span className="text-gray-500 text-sm font-bold uppercase">Total de Projetos</span>
                          <div className="text-3xl font-bold text-gray-800 mt-2">
                              {Object.values(groupedReports).flat().length}
                          </div>
                      </div>
                      <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                          <span className="text-gray-500 text-sm font-bold uppercase">Editais Ativos</span>
                          <div className="text-3xl font-bold text-prosas-blue mt-2">
                              {Object.keys(groupedReports).length}
                          </div>
                      </div>
                       <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                          <span className="text-gray-500 text-sm font-bold uppercase">Taxa de Aprovação</span>
                          <div className="text-3xl font-bold text-green-600 mt-2">
                              {(() => {
                                  const all = Object.values(groupedReports).flat();
                                  if (!all.length) return '0%';
                                  const approved = all.filter(r => r.result.overallStatus === 'APROVADO').length;
                                  return Math.round((approved / all.length) * 100) + '%';
                              })()}
                          </div>
                      </div>
                  </div>

                  <h2 className="text-lg font-bold text-gray-700 mb-4">Análises Recentes</h2>
                  <div className="bg-white rounded shadow-sm border border-gray-200 overflow-hidden">
                      <table className="w-full text-left text-sm text-gray-600">
                          <thead className="bg-gray-50 border-b border-gray-200 text-xs uppercase font-bold text-gray-500">
                              <tr>
                                  <th className="px-6 py-4">Organização</th>
                                  <th className="px-6 py-4">Edital</th>
                                  <th className="px-6 py-4">Data</th>
                                  <th className="px-6 py-4">Status</th>
                                  <th className="px-6 py-4"></th>
                              </tr>
                          </thead>
                          <tbody className="divide-y divide-gray-100">
                              {Object.values(groupedReports).flat().sort((a,b) => b.timestamp - a.timestamp).map(report => (
                                  <tr key={report.id} className="hover:bg-gray-50 transition-colors cursor-pointer" onClick={() => { setSelectedReport(report); setStage(AppStage.REPORT_VIEW); }}>
                                      <td className="px-6 py-4 font-medium text-gray-800">{report.candidateName}</td>
                                      <td className="px-6 py-4 text-gray-500">{report.editalName}</td>
                                      <td className="px-6 py-4">{new Date(report.timestamp).toLocaleDateString()}</td>
                                      <td className="px-6 py-4">
                                          <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold ${
                                              report.result.overallStatus === 'APROVADO' ? 'bg-green-100 text-green-700' :
                                              report.result.overallStatus === 'REPROVADO' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'
                                          }`}>
                                              <span className={`w-1.5 h-1.5 rounded-full ${
                                                  report.result.overallStatus === 'APROVADO' ? 'bg-green-500' :
                                                  report.result.overallStatus === 'REPROVADO' ? 'bg-red-500' : 'bg-yellow-500'
                                              }`}></span>
                                              {report.result.overallStatus}
                                          </span>
                                      </td>
                                      <td className="px-6 py-4 text-right">
                                          <i className="fas fa-chevron-right text-gray-300"></i>
                                      </td>
                                  </tr>
                              ))}
                              {Object.values(groupedReports).flat().length === 0 && (
                                  <tr>
                                      <td colSpan={5} className="px-6 py-12 text-center text-gray-400">
                                          Nenhuma análise realizada ainda.
                                      </td>
                                  </tr>
                              )}
                          </tbody>
                      </table>
                  </div>
              </div>
          )}

          {/* VIEW: SETUP */}
          {stage === AppStage.ANALYSIS_SETUP && (
               <div className="max-w-4xl mx-auto animate-fade-in">
                   <div className="flex items-center gap-4 mb-8">
                       <button onClick={() => setStage(AppStage.DASHBOARD)} className="w-10 h-10 rounded-full bg-white border border-gray-200 flex items-center justify-center text-gray-500 hover:text-prosas-blue transition-colors">
                           <i className="fas fa-arrow-left"></i>
                       </button>
                       <h1 className="text-2xl font-bold text-gray-800">Nova Rodada de Análise</h1>
                   </div>

                   <div className="bg-white p-8 rounded-lg shadow-sm border border-gray-200 mb-8">
                        <div className="flex items-center gap-3 mb-6">
                            <div className="p-2 bg-blue-100 text-prosas-blue rounded-lg">
                                <i className="fas fa-sliders-h text-xl"></i>
                            </div>
                            <div>
                                <h2 className="text-lg font-bold text-gray-800">1. Contexto do Edital</h2>
                                <p className="text-sm text-gray-500">Defina as regras que a IA usará para todos os candidatos desta rodada.</p>
                            </div>
                        </div>

                        <div className="grid md:grid-cols-2 gap-6">
                             <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 hover:bg-gray-50 transition text-center">
                                <i className="fas fa-book text-3xl text-gray-300 mb-3"></i>
                                <h3 className="font-bold text-gray-700 text-sm mb-1">Regulamento (PDF)</h3>
                                <p className="text-xs text-gray-400 mb-4">Arquivo principal com as regras.</p>
                                <label className="cursor-pointer bg-white border border-gray-300 hover:border-prosas-blue text-gray-600 px-4 py-2 rounded text-xs font-bold transition-colors">
                                    <input type="file" accept="application/pdf" className="hidden" onChange={(e) => handleContextUpload(e, 'regulation')} />
                                    {context.regulationText ? 'Arquivo OK' : 'Selecionar'}
                                </label>
                             </div>

                             <div className="border border-gray-200 rounded-lg p-4 bg-gray-50">
                                <h3 className="font-bold text-gray-700 text-sm mb-2">Critérios de Prompt</h3>
                                <textarea 
                                    className="w-full h-32 p-3 text-xs border border-gray-300 rounded focus:ring-1 focus:ring-prosas-blue outline-none"
                                    value={context.criteriaText}
                                    onChange={(e) => setContext({...context, criteriaText: e.target.value})}
                                />
                             </div>
                        </div>

                        <div className="flex justify-end mt-6">
                             <button 
                                onClick={() => setStage(AppStage.ANALYSIS_RUN)}
                                disabled={!context.regulationText}
                                className={`font-bold py-3 px-8 rounded shadow transition-all flex items-center gap-2 uppercase tracking-wide text-sm ${
                                    !context.regulationText ? 'bg-gray-300 cursor-not-allowed text-gray-500' : 'bg-prosas-blue hover:bg-prosas-blueDark text-white'
                                }`}
                            >
                                Avançar <i className="fas fa-arrow-right"></i>
                            </button>
                        </div>
                   </div>
               </div>
          )}

          {/* VIEW: RUNNER */}
          {stage === AppStage.ANALYSIS_RUN && (
               <div className="max-w-[1600px] mx-auto animate-fade-in">
                   <div className="flex items-center justify-between mb-8">
                       <div className="flex items-center gap-4">
                           <button onClick={() => setStage(AppStage.ANALYSIS_SETUP)} className="w-10 h-10 rounded-full bg-white border border-gray-200 flex items-center justify-center text-gray-500 hover:text-prosas-blue transition-colors">
                               <i className="fas fa-arrow-left"></i>
                           </button>
                           <div>
                                <h1 className="text-2xl font-bold text-gray-800">Upload de Projetos</h1>
                                <p className="text-sm text-gray-500">Edital Ativo: <strong>{context.editalTitle}</strong></p>
                           </div>
                       </div>
                   </div>

                   <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                        {candidates.map((candidate, index) => (
                            <div key={index} className="flex flex-col h-full min-h-[500px]">
                                {!candidate ? (
