                                        <div className="w-14 h-14 bg-gray-50 text-gray-400 rounded-full flex items-center justify-center mb-4 text-xl font-bold">
                                            {index + 1}
                                        </div>
                                        <h3 className="text-lg font-bold text-gray-700 mb-2">Slot Disponível</h3>
                                        <label className="cursor-pointer bg-prosas-blue hover:bg-prosas-blueDark text-white font-bold py-3 px-6 rounded shadow transition-all flex items-center gap-2 text-sm uppercase tracking-wide mt-4">
                                            <input type="file" accept="application/pdf" multiple onChange={(e) => handleSlotUpload(e, index)} className="hidden" />
                                            <i className="fas fa-upload"></i> Carregar Projeto
                                        </label>
                                    </div>
                                ) : (
