  const [context, setContext] = useState<AuditContext>({
    editalTitle: '',
    regulationText: '',
    formTemplateText: '',
    miscFilesText: '',
    criteriaText: DEFAULT_DOCUMENT_CRITERIA,
    isReady: false
  });
  const [candidates, setCandidates] = useState<(CandidateAnalysis | null)[]>([null, null, null]);

  // Load reports on mount or stage change
  useEffect(() => {
    if (stage === AppStage.DASHBOARD) {
      setGroupedReports(getReportsByEdital());
    }
  }, [stage]);

  const handleLocalLogin = () => {
      setUser({
          name: "Administrador",
          email: "admin@prosas.local",
          avatarUrl: "https://ui-avatars.com/api/?name=Admin+Prosas&background=C13B2E&color=fff&size=128"
      });
      setStage(AppStage.DASHBOARD);
