        const result = await runDocumentAudit(
            context.regulationText,
            context.formTemplateText,
            context.miscFilesText,
            context.criteriaText,
            files
        );

        // Save immediately to DB
        const saved = saveReport(context.editalTitle, result);

        // Update Slot
        setCandidates(prev => {
            const newSlots = [...prev];
            if (newSlots[slotIndex]) {
                newSlots[slotIndex] = {
                    ...newSlots[slotIndex]!,
                    status: 'completed',
                    result: result,
                    candidateName: result.candidateName || "Candidato Identificado"
                };
            }
            return newSlots;
        });

      } catch (err: any) {
          setCandidates(prev => {
            const newSlots = [...prev];
            if (newSlots[slotIndex]) {
                newSlots[slotIndex] = { ...newSlots[slotIndex]!, status: 'error', error: err.message };
            }
            return newSlots;
          });
      }
  };

  const clearSlot = (slotIndex: number) => {
      setCandidates(prev => {
          const newSlots = [...prev];
