                                                        editalName: context.editalTitle,
                                                        candidateName: candidate.candidateName,
                                                        cnpj: candidate.result!.organizationData.cnpj,
                                                        timestamp: Date.now(),
                                                        result: candidate.result!
                                                    }); setStage(AppStage.REPORT_VIEW); }}
                                                    className="w-full bg-prosas-blue hover:bg-prosas-blueDark text-white font-bold py-2 rounded text-sm transition-colors shadow-sm mb-2"
                                                >
                                                    <i className="fas fa-file-alt mr-2"></i> Ver Relatório
                                                </button>
                                                <div className="text-[10px] text-gray-400">
                                                    Salvo automaticamente
                                                </div>
                                            </div>
                                        )}

                                        {/* State: ERROR */}
                                        {candidate.status === 'error' && (
                                            <div className="text-center text-red-600 p-2">
                                                <i className="fas fa-exclamation-triangle text-2xl mb-2"></i>
                                                <p className="text-xs font-bold">Falha na análise</p>
                                                <p className="text-xs mt-1 mb-4">{candidate.error}</p>
                                                <button 
                                                    onClick={() => triggerAnalysis(candidate.slotId)}
                                                    className="text-xs bg-white border border-red-200 text-red-600 px-3 py-1 rounded hover:bg-red-50"
                                                >
                                                    Tentar Novamente
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}

                        {/* Empty State Helper */}
                        {candidates.length === 0 && (
                            <div className="col-span-full py-12 text-center text-gray-400 border-2 border-dashed border-gray-200 rounded-lg">
                                <p>Nenhum candidato na mesa de análise.</p>
                                <button onClick={addNewSlot} className="text-prosas-blue font-bold hover:underline mt-2">Adicionar o primeiro</button>
                            </div>
                        )}
                   </div>
               </div>
          )}

      </main>
    </div>
  );
};

