        alert("Erro ao ler arquivo: " + err);
    } finally {
        setLoadingContext(false);
    }
  };

  // 1. Adicionar novo slot vazio
  const addNewSlot = () => {
      if (candidates.length >= MAX_CONCURRENT_SLOTS) {
          alert(`Para garantir a estabilidade e economia de tokens, limitamos a ${MAX_CONCURRENT_SLOTS} análises simultâneas.`);
          return;
