                       </div>

                       <button 
                         onClick={addNewSlot}
                         disabled={candidates.length >= MAX_CONCURRENT_SLOTS}
                         className={`px-4 py-2 rounded font-bold text-sm flex items-center gap-2 ${
                             candidates.length >= MAX_CONCURRENT_SLOTS ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-prosas-blue text-white hover:bg-prosas-blueDark shadow-sm'
                         }`}
                       >
