                   </div>

                   {/* Dynamic Grid */}
                   <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                        {candidates.map((candidate, index) => (
                            <div key={candidate.slotId} className="flex flex-col h-full min-h-[400px] animate-fade-in-up">
                                <ProjectCard 
                                    project={candidate} 
                                    index={index} 
                                    criteriaText={context.criteriaText} // PASSED HERE
                                    onDelete={() => removeSlot(candidate.slotId)}
                                    onTrigger={() => triggerAnalysis(candidate.slotId)}
                                    onFileSelect={(e) => handleSlotFilesSelected(e, candidate.slotId)}
                                    onReset={() => setCandidates(prev => prev.map(c => c.slotId === candidate.slotId ? {...c, files: [], candidateName: ""} : c))}
                                    onViewReport={(report) => {
                                        setSelectedReport(report);
                                        setStage(AppStage.REPORT_VIEW);
                                    }}
                                />
                            </div>
                        ))}

                        {/* Empty State Helper */}
                        {candidates.length === 0 && (
                            <div className="col-span-full py-12 text-center text-gray-400 border-2 border-dashed border-gray-200 rounded-lg">
                                <p>Nenhum candidato na mesa de análise.</p>
                                <button onClick={addNewSlot} className="text-prosas-blue font-bold hover:underline mt-2">Adicionar o primeiro</button>
                            </div>
                        )}
                   </div>
               </div>
          )}

      </main>
    </div>
  );
};

