import React, { useState, useEffect, useMemo } from 'react';
import { CandidateAnalysis, SavedReport } from '../types';

interface Props {
  project: CandidateAnalysis;
  index: number;
  criteriaText: string;
  onDelete: () => void;
  onTrigger: () => void;
  onFileSelect: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onReset: () => void;
  onViewReport: (report: SavedReport) => void;
}

const ProjectCard: React.FC<Props> = ({ 
    project, 
    index, 
    criteriaText,
    onDelete,
    onTrigger,
    onFileSelect,
    onReset,
    onViewReport
}) => {
  // Parsing criteria headers for the progress visualization
  // Looks for "1. Title:" or "1. TITLE" patterns
  const criteriaList = useMemo(() => {
      const regex = /^\d+\.\s+(.+?)(?::|\n|$)/gm;
      const matches = [];
      let match;
      while ((match = regex.exec(criteriaText)) !== null) {
          matches.push(match[1].trim());
      }
      return matches.length > 0 ? matches : ["Análise Geral", "Validação de Documentos", "Regras de Negócio", "Conclusão"];
  }, [criteriaText]);

  // Simulation State
  const [activeCriterionIndex, setActiveCriterionIndex] = useState(0);

  useEffect(() => {
      let interval: any;
      if (project.status === 'analyzing') {
          setActiveCriterionIndex(0);
          // Simulate progress: Advance one step every ~4 seconds
          interval = setInterval(() => {
              setActiveCriterionIndex(prev => {
                  if (prev < criteriaList.length - 1) return prev + 1;
                  return prev;
              });
          }, 4000);
      } else if (project.status === 'completed') {
          setActiveCriterionIndex(criteriaList.length); // All done
      }
      return () => clearInterval(interval);
  }, [project.status, criteriaList.length]);


  return (
    <div className="bg-white rounded-lg shadow-md border border-gray-200 flex flex-col h-full overflow-hidden relative transition-all duration-300 hover:shadow-lg">

        {/* Card Header */}
        <div className="p-4 border-b border-gray-100 flex justify-between items-start bg-gray-50">
            <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-full bg-gray-200 flex items-center justify-center text-gray-500 font-bold text-sm">
                    {index + 1}
                </div>
                <div>
                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded mb-1 inline-block uppercase tracking-wider ${
                            project.status === 'completed' ? 'bg-green-100 text-green-700' : 
                            project.status === 'analyzing' ? 'bg-blue-100 text-blue-700' : 
                            project.status === 'error' ? 'bg-red-100 text-red-700' : 'bg-gray-100 text-gray-500'
                        }`}>
                            {project.status === 'completed' ? 'FINALIZADO' : 
                            project.status === 'analyzing' ? 'EM ANÁLISE' : 
                            project.status === 'error' ? 'ERRO' : 'PENDENTE'}
                        </span>
                        <h3 className="font-bold text-gray-800 text-sm truncate w-48" title={project.candidateName || "Novo Candidato"}>
                            {project.candidateName || "Novo Candidato"}
                        </h3>
                </div>
            </div>
            <button onClick={onDelete} className="text-gray-300 hover:text-red-500 transition-colors p-1" title="Remover Slot">
                <i className="fas fa-trash-alt"></i>
            </button>
        </div>

        {/* Card Body */}
        <div className="p-6 flex-grow flex flex-col items-center justify-center relative w-full">

            {/* State: PENDING (Upload or Start) */}
            {project.status === 'pending' && (
                <div className="text-center w-full">
                    {project.files && project.files.length > 0 ? (
                        <div className="animate-fade-in">
                            <div className="mb-6">
                                <i className="fas fa-file-pdf text-4xl text-red-500 mb-2"></i>
                                <p className="text-sm font-medium text-gray-700">{project.files.length} arquivo(s) pronto(s)</p>
                                <p className="text-xs text-gray-400 mt-1 truncate max-w-[200px] mx-auto">{project.files[0].name}</p>
                            </div>
                            <button 
                                onClick={onTrigger}
                                className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-2 px-4 rounded shadow-sm transition-all flex items-center justify-center gap-2"
                            >
                                <i className="fas fa-play"></i> Iniciar Análise
                            </button>
                            <button 
                                onClick={onReset}
                                className="mt-3 text-xs text-gray-400 hover:text-red-500 underline"
                            >
                                Trocar arquivos
                            </button>
                        </div>
                    ) : (
                        <div>
                            <i className="fas fa-cloud-upload-alt text-gray-300 text-4xl mb-3"></i>
                            <p className="text-sm text-gray-400 mb-4">Proposta (PDFs ou ZIP)</p>
                            <label className="cursor-pointer bg-white border border-gray-300 hover:border-prosas-blue text-gray-600 font-bold py-2 px-4 rounded transition-all inline-flex items-center gap-2 text-sm">
                                <input type="file" accept="application/pdf,.zip" multiple onChange={onFileSelect} className="hidden" />
                                Selecionar Arquivos
                            </label>
                        </div>
                    )}
                </div>
            )}

            {/* State: ANALYZING (Progress Visualization) */}
            {project.status === 'analyzing' && (
                <div className="w-full text-left animate-fade-in">
                    <div className="flex items-center justify-between mb-2">
                        <span className="text-xs font-bold text-prosas-blue animate-pulse">
                            <i className="fas fa-search mr-1"></i> Auditando...
                        </span>
                        <span className="text-xs text-gray-400">
                             {Math.min(activeCriterionIndex + 1, criteriaList.length)} / {criteriaList.length}
                        </span>
                    </div>

                    {/* Progress Bar */}
                    <div className="w-full bg-gray-100 rounded-full h-1.5 mb-4 overflow-hidden">
                        <div 
                            className="bg-prosas-blue h-1.5 rounded-full transition-all duration-500 ease-out"
                            style={{ width: `${((activeCriterionIndex + 1) / criteriaList.length) * 100}%` }}
                        ></div>
                    </div>

                    {/* Criteria Checklist Animation */}
                    <div className="space-y-2 max-h-40 overflow-y-auto custom-scrollbar pr-1">
                        {criteriaList.map((criterion, idx) => (
                            <div key={idx} className={`flex items-center gap-2 text-xs transition-colors duration-300 ${
                                idx < activeCriterionIndex ? 'text-green-600 font-medium' :
                                idx === activeCriterionIndex ? 'text-gray-800 font-bold' :
                                'text-gray-300'
                            }`}>
                                <i className={`fas ${
                                    idx < activeCriterionIndex ? 'fa-check-circle' :
                                    idx === activeCriterionIndex ? 'fa-spinner fa-spin' :
                                    'fa-circle'
                                } text-[10px]`}></i>
                                <span className="truncate">{criterion}</span>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* State: COMPLETED */}
            {project.status === 'completed' && project.result && (
                <div className="text-center w-full animate-fade-in">
                    <div className={`w-14 h-14 rounded-full flex items-center justify-center text-2xl mx-auto mb-3 ${
                        project.result.overallStatus === 'APROVADO' ? 'bg-green-100 text-green-600' : 
                        project.result.overallStatus === 'REPROVADO' ? 'bg-red-100 text-red-600' : 'bg-yellow-100 text-yellow-600'
                    }`}>
                        <i className={`fas ${project.result.overallStatus === 'APROVADO' ? 'fa-check' : 'fa-times'}`}></i>
                    </div>
                    <h3 className="font-bold text-lg mb-1">{project.result.overallStatus}</h3>
                    <p className="text-xs text-gray-500 mb-4 px-2 line-clamp-2">{project.result.summary}</p>

                    <button 
                        onClick={() => onViewReport({
                            id: project.id,
                            editalName: "Edital Atual", // Should ideally be passed down
                            candidateName: project.candidateName,
                            cnpj: project.result!.organizationData.cnpj,
                            timestamp: Date.now(),
                            result: project.result!
                        })}
                        className="w-full bg-prosas-blue hover:bg-prosas-blueDark text-white font-bold py-2 rounded text-sm transition-colors shadow-sm mb-2"
                    >
                        <i className="fas fa-file-alt mr-2"></i> Ver Relatório
                    </button>
                    <div className="text-[10px] text-gray-400">
                        Salvo automaticamente
                    </div>
                </div>
            )}

            {/* State: ERROR */}
            {project.status === 'error' && (
                <div className="text-center text-red-600 p-2">
                    <i className="fas fa-exclamation-triangle text-2xl mb-2"></i>
                    <p className="text-xs font-bold">Falha na análise</p>
                    <p className="text-xs mt-1 mb-4">{project.error}</p>
                    <button 
                        onClick={onTrigger}
                        className="text-xs bg-white border border-red-200 text-red-600 px-3 py-1 rounded hover:bg-red-50"
                    >
                        Tentar Novamente
                    </button>
                </div>
            )}
        </div>
    </div>
  );
};

