                                     {point.status !== 'OK' && (
                                         <p className="text-gray-500 mt-0.5">{point.justification}</p>
                                     )}
                                 </div>
                             </div>
                         ))}
                    </div>

                    <button 
                        onClick={() => onViewReport({
                            id: project.id,
                            editalName: "Edital", 
                            candidateName: project.candidateName,
                            cnpj: project.result!.organizationData.cnpj,
                            timestamp: Date.now(),
                            result: project.result!
                        })}
                        className="w-full bg-white border border-gray-300 hover:border-prosas-blue hover:text-prosas-blue text-gray-600 font-bold py-2 rounded text-xs transition-colors shadow-sm"
                    >
                        Ver Relatório Completo
                    </button>
                </div>
            )}

            {/* ERROR */}
            {project.status === 'error' && (
                <div className="text-center text-red-600 p-2 animate-pulse">
                    <div className="bg-red-50 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-3">
                        <i className="fas fa-server text-3xl"></i>
                    </div>
                    <p className="text-sm font-bold mb-1">Interrupção na Análise</p>
                    <p className="text-xs text-red-500 mb-4 px-2">{project.error}</p>
                    <button 
                        onClick={onTrigger}
                        className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded text-xs font-bold shadow-sm transition-colors"
                    >
                        <i className="fas fa-sync-alt mr-1"></i> Tentar Novamente
                    </button>
                </div>
            )}
        </div>
    </div>
  );
};

