import { GoogleGenAI } from "@google/genai";
import { SYSTEM_INSTRUCTION, USER_TASK_PROMPT } from "../constants";
import { fileToBase64 } from "./pdfService";
import { AuditResult } from "../types";

const getClient = () => {
    if (!process.env.API_KEY) {
        throw new Error("API Key is missing.");
    }
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

// Helper para economizar tokens removendo espaços vazios excessivos
const sanitizeText = (text: string) => {
    return text.replace(/\s+/g, ' ').trim();
};

export const runDocumentAudit = async (
    regulation: string,
    formTemplate: string,
    miscFiles: string,
    criteria: string,
    candidateFiles: File[]
): Promise<AuditResult> => {
    const ai = getClient();
    const model = 'gemini-2.0-flash-exp'; // Modelo mais eficiente/rápido atualmente

    // 1. Otimização de Imagens/PDFs
    // Convertemos para Base64. Gemini Flash suporta PDFs nativamente via inlineData.
    const fileParts = await Promise.all(candidateFiles.map(async (file) => {
        const base64Data = await fileToBase64(file);
        return {
            inlineData: {
                data: base64Data,
                mimeType: "application/pdf"
            }
        };
    }));

    // 2. Configuração do Contexto (System Instruction)
    // Isso separa as regras dos dados, economizando confusão da IA.
    const systemInstructionText = SYSTEM_INSTRUCTION(
        sanitizeText(regulation), 
        sanitizeText(formTemplate), 
        sanitizeText(miscFiles), 
        criteria
    );

    // 3. Prompt do Usuário (Simples e direto)
    const parts = [{ text: USER_TASK_PROMPT }, ...fileParts];

    const jsonString = await generateContentWithSmartRetry(ai, model, parts, systemInstructionText);

    try {
        const cleaned = jsonString.replace(/```json/g, '').replace(/```/g, '').trim();
        return JSON.parse(cleaned) as AuditResult;
    } catch (e) {
        console.error("JSON Parse Error", jsonString);
        throw new Error("A IA retornou um formato inválido. Verifique se os arquivos não estão corrompidos.");
    }
};

/**
 * Lógica de Retry Otimizada para evitar desperdício de tokens em loops infinitos.
 * Só retenta em erros transientes (Rate Limit ou Server Overload).
 */
const generateContentWithSmartRetry = async (
    ai: GoogleGenAI, 
    model: string, 
    parts: any[], 
    systemInstruction: string,
    retries = 3, // Reduzido para 3 para falhar mais rápido se a cota acabou de verdade
    baseDelay = 8000 // Aumentado para 8s base
): Promise<string> => {
    for (let i = 0; i < retries; i++) {
        try {
            const response = await ai.models.generateContent({
                model: model,
                contents: { parts: parts },
                config: {
                    systemInstruction: systemInstruction,
                    temperature: 0.1, // Baixa criatividade para auditoria
                    candidateCount: 1,
                    responseMimeType: "application/json"
                }
            });
            return response.text || "";
        } catch (error: any) {
            let status = error.status || error.response?.status;
            let errorMessage = error.message || JSON.stringify(error);

            // Tentar extrair status do JSON string se o erro vier "envelopado"
            if (errorMessage.includes("RESOURCE_EXHAUSTED") || errorMessage.includes("429")) {
                status = 429;
            }

            // 429 = Too Many Requests (Rate Limit)
            // 503 = Service Unavailable (Overload)
            const isRateLimit = status === 429;
            const isServerOverload = status === 503;

            if ((isRateLimit || isServerOverload) && i < retries - 1) {
                // Se for Rate Limit (429), precisamos de um delay MUITO maior.
                // Estratégia Agressiva: 8s, 16s, 32s
                const waitTime = baseDelay * Math.pow(2, i);

                console.warn(`Erro ${status} (Tentativa ${i + 1}/${retries}). Aguardando ${waitTime/1000}s...`);
                await new Promise(resolve => setTimeout(resolve, waitTime));
                continue;
            }

            // Tratamento final de erro para exibição limpa
            console.error("Erro fatal na API Gemini:", error);

            if (isRateLimit) {
                throw new Error("Cota de uso da IA excedida (Erro 429). O plano gratuito tem limites. Aguarde 1-2 minutos.");
            }

            if (errorMessage.includes("400")) {
                throw new Error("Erro nos arquivos enviados (Bad Request). Verifique se os PDFs são válidos.");
            }

            // Limpa a mensagem JSON bruta se ela vazar
            if (errorMessage.startsWith('{') && errorMessage.includes('"message":')) {
                try {
                    const parsed = JSON.parse(errorMessage);
                    throw new Error(parsed.error?.message || "Erro desconhecido na API.");
                } catch (e) {
                    throw new Error("Erro técnico na comunicação com a IA.");
                }
            }

            throw error; 
        }
    }
    throw new Error("O servidor da IA está muito ocupado no momento. Tente novamente em 2 minutos.");
};

