                  >
                      <i className="fas fa-th-large"></i> Visão Geral
                  </button>

                  {Object.keys(groupedReports).map(editalName => (
                      <div key={editalName} className="mt-4">
                          <div className="px-3 py-1 text-xs font-bold text-gray-500 flex items-center gap-2 truncate" title={editalName}>
                              <i className="fas fa-folder text-yellow-400"></i> {editalName}
                          </div>
                          <div className="ml-4 mt-1 space-y-0.5 border-l-2 border-gray-100 pl-2">
                              {groupedReports[editalName].map(report => (
                                  <button 
                                    key={report.id}
                                    onClick={() => { setSelectedReport(report); setStage(AppStage.REPORT_VIEW); }}
                                    className="w-full text-left px-2 py-1.5 rounded text-xs text-gray-500 hover:text-prosas-blue hover:bg-gray-50 truncate transition-colors flex justify-between items-center group"
                                  >
                                      <span className="truncate">{report.candidateName}</span>
                                      <span className={`w-2 h-2 rounded-full flex-shrink-0 ${
                                          report.result.overallStatus === 'APROVADO' ? 'bg-green-400' : 'bg-red-400'
                                      }`}></span>
                                  </button>
                              ))}
                          </div>
                      </div>
                  ))}
              </div>
          </nav>

          <div className="p-4 border-t border-gray-100">
              <div className="flex items-center gap-3 mb-3">
                  <img src={user?.avatarUrl} alt="User" className="w-8 h-8 rounded-full border border-gray-200" />
                  <div className="overflow-hidden">
                      <p className="text-sm font-bold text-gray-800 truncate" title={user?.name}>{user?.name}</p>
                      <p className="text-xs text-gray-500 truncate" title={user?.email}>{user?.email}</p>
                  </div>
              </div>
              <button 
                  onClick={handleLogout}
                  className="w-full text-xs text-gray-500 hover:text-red-600 flex items-center justify-center gap-2 py-1"
              >
                  <i className="fas fa-sign-out-alt"></i> Sair
              </button>
          </div>
      </aside>

      {/* MAIN CONTENT - Adicionado print:h-auto print:overflow-visible */}
      <main className="flex-1 overflow-y-auto h-screen bg-gray-50 p-8 print:p-0 print:h-auto print:overflow-visible print:bg-white">

          {/* VIEW: REPORT VIEWER (IDWALL STYLE) */}
          {stage === AppStage.REPORT_VIEW && selectedReport && (
              <ReportViewer report={selectedReport} onBack={() => setStage(AppStage.DASHBOARD)} />
          )}

          {/* VIEW: DASHBOARD */}
          {stage === AppStage.DASHBOARD && (
              <div className="max-w-6xl mx-auto animate-fade-in">
                  <h1 className="text-2xl font-bold text-gray-800 mb-6">Visão Geral das Análises</h1>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                      <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                          <span className="text-gray-500 text-sm font-bold uppercase">Total de Projetos</span>
                          <div className="text-3xl font-bold text-gray-800 mt-2">
                              {Object.values(groupedReports).flat().length}
                          </div>
                      </div>
                      <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                          <span className="text-gray-500 text-sm font-bold uppercase">Editais Ativos</span>
                          <div className="text-3xl font-bold text-prosas-blue mt-2">
                              {Object.keys(groupedReports).length}
                          </div>
                      </div>
                       <div className="bg-white p-6 rounded shadow-sm border border-gray-200">
                          <span className="text-gray-500 text-sm font-bold uppercase">Taxa de Aprovação</span>
                          <div className="text-3xl font-bold text-green-600 mt-2">
                              {(() => {
                                  const all = Object.values(groupedReports).flat();
                                  if (!all.length) return '0%';
                                  const approved = all.filter(r => r.result.overallStatus === 'APROVADO').length;
                                  return Math.round((approved / all.length) * 100) + '%';
                              })()}
                          </div>
                      </div>
                  </div>

                  <h2 className="text-lg font-bold text-gray-700 mb-4">Análises Recentes</h2>
                  <div className="bg-white rounded shadow-sm border border-gray-200 overflow-hidden">
                      <table className="w-full text-left text-sm text-gray-600">
                          <thead className="bg-gray-50 border-b border-gray-200 text-xs uppercase font-bold text-gray-500">
                              <tr>
                                  <th className="px-6 py-4">Organização</th>
                                  <th className="px-6 py-4">Edital</th>
                                  <th className="px-6 py-4">Data</th>
                                  <th className="px-6 py-4">Status</th>
                                  <th className="px-6 py-4"></th>
                              </tr>
                          </thead>
                          <tbody className="divide-y divide-gray-100">
                              {Object.values(groupedReports).flat().sort((a,b) => b.timestamp - a.timestamp).map(report => (
                                  <tr key={report.id} className="hover:bg-gray-50 transition-colors cursor-pointer" onClick={() => { setSelectedReport(report); setStage(AppStage.REPORT_VIEW); }}>
                                      <td className="px-6 py-4 font-medium text-gray-800">{report.candidateName}</td>
                                      <td className="px-6 py-4 text-gray-500">{report.editalName}</td>
                                      <td className="px-6 py-4">{new Date(report.timestamp).toLocaleDateString()}</td>
                                      <td className="px-6 py-4">
                                          <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold ${
                                              report.result.overallStatus === 'APROVADO' ? 'bg-green-100 text-green-700' :
                                              report.result.overallStatus === 'REPROVADO' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'
                                          }`}>
                                              <span className={`w-1.5 h-1.5 rounded-full ${
                                                  report.result.overallStatus === 'APROVADO' ? 'bg-green-500' :
                                                  report.result.overallStatus === 'REPROVADO' ? 'bg-red-500' : 'bg-yellow-500'
                                              }`}></span>
                                              {report.result.overallStatus}
                                          </span>
                                      </td>
                                      <td className="px-6 py-4 text-right">
                                          <i className="fas fa-chevron-right text-gray-300"></i>
                                      </td>
                                  </tr>
                              ))}
                              {Object.values(groupedReports).flat().length === 0 && (
                                  <tr>
                                      <td colSpan={5} className="px-6 py-12 text-center text-gray-400">
                                          Nenhuma análise realizada ainda.
                                      </td>
                                  </tr>
                              )}
                          </tbody>
                      </table>
                  </div>
              </div>
          )}

          {/* VIEW: SETUP */}
          {stage === AppStage.ANALYSIS_SETUP && (
               <div className="max-w-6xl mx-auto animate-fade-in pb-10">
                   <div className="flex items-center gap-4 mb-8">
                       <button onClick={() => setStage(AppStage.DASHBOARD)} className="w-10 h-10 rounded-full bg-white border border-gray-200 flex items-center justify-center text-gray-500 hover:text-prosas-blue transition-colors">
                           <i className="fas fa-arrow-left"></i>
                       </button>
                       <div>
                            <h1 className="text-2xl font-bold text-gray-800">Nova Rodada de Análise</h1>
                            <p className="text-sm text-gray-500">Configure o contexto e as regras para esta auditoria.</p>
                       </div>
                   </div>

                   {/* SECTION 1: DOCUMENT UPLOADS */}
                   <div className="bg-white p-8 rounded-lg shadow-sm border border-gray-200 mb-8">
                        <div className="flex items-center gap-3 mb-6 pb-4 border-b border-gray-100">
                            <div className="p-2 bg-blue-100 text-prosas-blue rounded-lg">
                                <i className="fas fa-folder-open text-xl"></i>
                            </div>
                            <div>
                                <h2 className="text-lg font-bold text-gray-800">1. Arquivos de Contexto</h2>
                                <p className="text-sm text-gray-500">Carregue os documentos que servirão de base para a IA.</p>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            {/* Regulation Card */}
                             <div className={`border-2 border-dashed rounded-lg p-6 flex flex-col items-center justify-center text-center transition-colors relative min-h-[200px] ${
                                 context.regulationText 
                                 ? 'border-green-400 bg-green-50' 
                                 : 'border-gray-300 hover:border-prosas-blue hover:bg-gray-50'
                             }`}>
                                {context.regulationText && (
                                    <div className="absolute top-3 right-3 text-green-600 bg-white rounded-full p-1 shadow-sm"><i className="fas fa-check-circle"></i></div>
                                )}
                                <i className={`fas fa-book text-4xl mb-4 ${context.regulationText ? 'text-green-500' : 'text-gray-300'}`}></i>
                                <h3 className="font-bold text-gray-700 text-sm mb-1">Regulamento (PDF)</h3>
                                <p className="text-xs text-gray-400 mb-4">Obrigatório. Contém as regras do edital.</p>
                                <label className={`cursor-pointer px-4 py-2 rounded text-xs font-bold transition-colors ${
                                    context.regulationText ? 'bg-white text-green-700 border border-green-200' : 'bg-white border border-gray-300 text-gray-600 hover:border-prosas-blue'
                                }`}>
                                    <input type="file" accept="application/pdf" className="hidden" onChange={(e) => handleContextUpload(e, 'regulation')} />
                                    {context.regulationText ? 'Arquivo Carregado' : 'Selecionar'}
                                </label>
                             </div>

                             {/* Form Template Card */}
                             <div className={`border-2 border-dashed rounded-lg p-6 flex flex-col items-center justify-center text-center transition-colors relative min-h-[200px] ${
                                 context.formTemplateText 
                                 ? 'border-blue-400 bg-blue-50' 
                                 : 'border-gray-300 hover:border-prosas-blue hover:bg-gray-50'
                             }`}>
                                {context.formTemplateText && (
                                    <div className="absolute top-3 right-3 text-blue-600 bg-white rounded-full p-1 shadow-sm"><i className="fas fa-check-circle"></i></div>
                                )}
                                <i className={`fas fa-file-alt text-4xl mb-4 ${context.formTemplateText ? 'text-blue-500' : 'text-gray-300'}`}></i>
                                <h3 className="font-bold text-gray-700 text-sm mb-1">Modelo de Formulário</h3>
                                <p className="text-xs text-gray-400 mb-4">Opcional. Estrutura da proposta.</p>
                                <label className={`cursor-pointer px-4 py-2 rounded text-xs font-bold transition-colors ${
                                    context.formTemplateText ? 'bg-white text-blue-700 border border-blue-200' : 'bg-white border border-gray-300 text-gray-600 hover:border-prosas-blue'
                                }`}>
                                    <input type="file" accept="application/pdf" className="hidden" onChange={(e) => handleContextUpload(e, 'form')} />
                                    {context.formTemplateText ? 'Carregado' : 'Selecionar'}
                                </label>
                             </div>

                             {/* Misc Files Card */}
                             <div className={`border-2 border-dashed rounded-lg p-6 flex flex-col items-center justify-center text-center transition-colors relative min-h-[200px] ${
                                 context.miscFilesText 
                                 ? 'border-blue-400 bg-blue-50' 
                                 : 'border-gray-300 hover:border-prosas-blue hover:bg-gray-50'
                             }`}>
                                {context.miscFilesText && (
                                    <div className="absolute top-3 right-3 text-blue-600 bg-white rounded-full p-1 shadow-sm"><i className="fas fa-check-circle"></i></div>
                                )}
                                <i className={`fas fa-paperclip text-4xl mb-4 ${context.miscFilesText ? 'text-blue-500' : 'text-gray-300'}`}></i>
                                <h3 className="font-bold text-gray-700 text-sm mb-1">Outros Anexos</h3>
                                <p className="text-xs text-gray-400 mb-4">Opcional. Manuais ou erratas.</p>
                                <label className={`cursor-pointer px-4 py-2 rounded text-xs font-bold transition-colors ${
                                    context.miscFilesText ? 'bg-white text-blue-700 border border-blue-200' : 'bg-white border border-gray-300 text-gray-600 hover:border-prosas-blue'
                                }`}>
                                    <input type="file" accept="application/pdf" className="hidden" onChange={(e) => handleContextUpload(e, 'misc')} />
                                    {context.miscFilesText ? 'Carregado' : 'Selecionar'}
                                </label>
                             </div>
                        </div>
                   </div>

                   {/* SECTION 2: PROMPT CRITERIA */}
                   <div className="bg-white p-8 rounded-lg shadow-sm border border-gray-200 mb-8">
                        <div className="flex items-center gap-3 mb-6 pb-4 border-b border-gray-100">
                            <div className="p-2 bg-yellow-100 text-yellow-600 rounded-lg">
                                <i className="fas fa-magic text-xl"></i>
                            </div>
                            <div>
                                <h2 className="text-lg font-bold text-gray-800">2. Critérios da IA (Prompt)</h2>
                                <p className="text-sm text-gray-500">Edite as regras lógicas que a IA usará para aprovar ou reprovar.</p>
                            </div>
                        </div>

                        <div className="relative">
                            <textarea 
                                className="w-full h-96 p-6 text-sm font-mono text-gray-800 bg-gray-50 border border-gray-300 rounded-lg focus:ring-2 focus:ring-prosas-blue focus:bg-white outline-none resize-y leading-relaxed shadow-inner"
                                value={context.criteriaText}
                                onChange={(e) => setContext({...context, criteriaText: e.target.value})}
                                spellCheck={false}
                            />
                            <div className="absolute bottom-4 right-4 text-xs text-gray-400 bg-gray-100 px-2 py-1 rounded">
                                {context.criteriaText.length} caracteres
                            </div>
                        </div>
                   </div>

                   {/* ACTION FOOTER */}
                   <div className="flex items-center justify-between bg-white p-4 rounded-lg shadow-sm border border-gray-200 sticky bottom-4">
                        <div className="text-sm">
                            <span className="text-gray-500">Status: </span>
                            {context.regulationText ? (
                                <span className="font-bold text-green-600"><i className="fas fa-check mr-1"></i> Regulamento OK</span>
                            ) : (
                                <span className="font-bold text-red-500">Aguardando Regulamento</span>
                            )}
                        </div>
                        <button 
                            onClick={() => {
                                // Se não houver candidatos, adiciona o primeiro automaticamente
                                if (candidates.length === 0) addNewSlot();
                                setStage(AppStage.ANALYSIS_RUN);
                            }}
                            disabled={!context.regulationText}
                            className={`font-bold py-3 px-8 rounded shadow transition-all flex items-center gap-2 uppercase tracking-wide text-sm ${
                                !context.regulationText ? 'bg-gray-300 cursor-not-allowed text-gray-500' : 'bg-prosas-blue hover:bg-prosas-blueDark text-white'
                            }`}
                        >
                            Ir para Análise <i className="fas fa-arrow-right"></i>
                        </button>
                   </div>
               </div>
          )}

          {/* VIEW: RUNNER (NOVA VERSÃO DINÂMICA) */}
          {stage === AppStage.ANALYSIS_RUN && (
               <div className="max-w-[1600px] mx-auto animate-fade-in pb-10">
                   <div className="flex items-center justify-between mb-8 sticky top-0 bg-gray-50 z-10 py-4 border-b border-gray-200">
                       <div className="flex items-center gap-4">
                           <button onClick={() => setStage(AppStage.ANALYSIS_SETUP)} className="w-10 h-10 rounded-full bg-white border border-gray-200 flex items-center justify-center text-gray-500 hover:text-prosas-blue transition-colors">
                               <i className="fas fa-arrow-left"></i>
                           </button>
                           <div>
                                <h1 className="text-2xl font-bold text-gray-800">Execução da Análise</h1>
                                <p className="text-sm text-gray-500">Contexto: <strong>{context.editalTitle}</strong> | <span className="text-xs bg-gray-200 px-2 rounded">{candidates.length}/{MAX_CONCURRENT_SLOTS} slots</span></p>
                           </div>
                       </div>

                       <button 
                         onClick={addNewSlot}
                         disabled={candidates.length >= MAX_CONCURRENT_SLOTS}
                         className={`px-4 py-2 rounded font-bold text-sm flex items-center gap-2 ${
                             candidates.length >= MAX_CONCURRENT_SLOTS ? 'bg-gray-200 text-gray-400 cursor-not-allowed' : 'bg-prosas-blue text-white hover:bg-prosas-blueDark shadow-sm'
                         }`}
                       >
                           <i className="fas fa-plus"></i> Adicionar Candidato
                       </button>
                   </div>

                   {/* Dynamic Grid */}
                   <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                        {candidates.map((candidate, index) => (
                            <div key={candidate.slotId} className="flex flex-col h-full min-h-[400px] animate-fade-in-up">
                                <ProjectCard 
                                    project={candidate} 
                                    index={index} 
                                    criteriaText={context.criteriaText} // PASSED HERE
                                    onDelete={() => removeSlot(candidate.slotId)}
                                    onTrigger={() => triggerAnalysis(candidate.slotId)}
                                    onFileSelect={(e) => handleSlotFilesSelected(e, candidate.slotId)}
                                    onReset={() => setCandidates(prev => prev.map(c => c.slotId === candidate.slotId ? {...c, files: [], candidateName: ""} : c))}
                                    onViewReport={(report) => {
                                        setSelectedReport(report);
                                        setStage(AppStage.REPORT_VIEW);
                                    }}
                                />
                            </div>
                        ))}

                        {/* Empty State Helper */}
                        {candidates.length === 0 && (
                            <div className="col-span-full py-12 text-center text-gray-400 border-2 border-dashed border-gray-200 rounded-lg">
                                <p>Nenhum candidato na mesa de análise.</p>
                                <button onClick={addNewSlot} className="text-prosas-blue font-bold hover:underline mt-2">Adicionar o primeiro</button>
                            </div>
                        )}
                   </div>
               </div>
          )}

      </main>
    </div>
  );
};

export default App;
